175	export async function uploadSchreiben(dateiname, daten) {
176	  await fs.mkdir(UPLOAD_ORDNER, { recursive: true });
177	  await fs.writeFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)), daten);
178	}
179	
180	export async function uploadLesen(dateiname) {
181	  return fs.readFile(path.join(UPLOAD_ORDNER, path.basename(dateiname)));
182	}
183	
184	export async function uploadLoeschen(dateiname) {
185	  await fs.rm(path.join(UPLOAD_ORDNER, path.basename(dateiname)), { force: true });
186	}
  1	// src/lib/plattform/totp.js
  2	//
  3	// Zwei-Faktor-Anmeldung ohne Fremdpakete (nur Node-`crypto`, NUR serverseitig):
  4	//  - TOTP nach RFC 6238 (HMAC-SHA1, 30 s, 6 Stellen) auf Basis von HOTP (RFC 4226)
  5	//  - Base32 (RFC 4648) für den Schlüssel in Authenticator-Apps, otpauth-URI
  6	//  - Wiederherstellungscodes (einmalig, nur als SHA-256 gespeichert)
  7	//  - Verschlüsselung des TOTP-Schlüssels im Demo-Backend (AES-256-GCM). Frappe speichert den
  8	//    Schlüssel in einem Password-Feld (verschlüsselt mit dem encryption_key der Site).
  9	//
 10	// Replay-Schutz: `totpPruefen` liefert den Zeitschritt des akzeptierten Codes; das Backend speichert
 11	// ihn als `letzterSchritt` und akzeptiert danach nur noch spätere Schritte.
 12	
 13	import { createCipheriv, createDecipheriv, createHash, createHmac, randomBytes, timingSafeEqual } from "node:crypto";
 14	
 15	export const PERIODE_S = 30;
 16	export const STELLEN = 6;
 17	/** Toleranz ± Zeitschritte (Uhrabweichung des Telefons) */
 18	export const FENSTER = 1;
 19	export const AUSSTELLER = "ÖkoInvest";
 20	
 21	const B32 = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
 22	
 23	export function base32(buf) {
 24	  let bits = 0;
 25	  let wert = 0;
 26	  let out = "";
 27	  for (const byte of buf) {
 28	    wert = (wert << 8) | byte;
 29	    bits += 8;
 30	    while (bits >= 5) {
 31	      out += B32[(wert >>> (bits - 5)) & 31];
 32	      bits -= 5;
 33	    }
 34	  }
 35	  if (bits > 0) out += B32[(wert << (5 - bits)) & 31];
 36	  return out;
 37	}
 38	
 39	export function base32Lesen(s) {
 40	  const sauber = String(s || "").toUpperCase().replace(/[\s=-]/g, "");
 41	  let bits = 0;
 42	  let wert = 0;
 43	  const out = [];
 44	  for (const z of sauber) {
 45	    const i = B32.indexOf(z);
 46	    if (i < 0) throw new Error("Ungültiges Base32");
 47	    wert = (wert << 5) | i;
 48	    bits += 5;
 49	    if (bits >= 8) {
 50	      out.push((wert >>> (bits - 8)) & 255);
 51	      bits -= 8;
 52	    }
 53	  }
 54	  return Buffer.from(out);
 55	}
 56	
 57	/** Neuer TOTP-Schlüssel: 160 Bit (Empfehlung RFC 4226), Base32 */
 58	export const geheimnisErzeugen = () => base32(randomBytes(20));
 59	
 60	/** HOTP-Wert (RFC 4226) für Zähler `zaehler` */
 61	export function hotp(schluessel, zaehler, stellen = STELLEN, algo = "sha1") {
 62	  const b = Buffer.alloc(8);
 63	  b.writeBigUInt64BE(BigInt(zaehler));
 64	  const h = createHmac(algo, schluessel).update(b).digest();
 65	  const o = h[h.length - 1] & 0x0f;
 66	  const bin = ((h[o] & 0x7f) << 24) | (h[o + 1] << 16) | (h[o + 2] << 8) | h[o + 3];
 67	  return String(bin % 10 ** stellen).padStart(stellen, "0");
 68	}
 69	
 70	export const zeitschritt = (zeitMs = Date.now()) => Math.floor(zeitMs / 1000 / PERIODE_S);
 71	
 72	/** TOTP-Code eines Base32-Schlüssels zu einem Zeitpunkt (für Tests und Anzeige) */
 73	export const totp = (geheimnisB32, zeitMs = Date.now()) => hotp(base32Lesen(geheimnisB32), zeitschritt(zeitMs));
 74	
 75	function gleich(a, b) {
 76	  const x = Buffer.from(String(a));
 77	  const y = Buffer.from(String(b));
 78	  return x.length === y.length && timingSafeEqual(x, y);
 79	}
 80	
 81	/**
 82	 * Code prüfen. Liefert den Zeitschritt des passenden Codes oder null.
 83	 * Nur Schritte > `letzterSchritt` zählen (derselbe Code ist nie zweimal gültig).
 84	 */
 85	export function totpPruefen(geheimnisB32, code, { letzterSchritt = -1, zeitMs = Date.now(), fenster = FENSTER } = {}) {
 86	  const c = String(code || "").replace(/\s/g, "");
 87	  if (!/^\d{6}$/.test(c) || !geheimnisB32) return null;
 88	  const schluessel = base32Lesen(geheimnisB32);
 89	  const jetzt = zeitschritt(zeitMs);
 90	  let treffer = null;
 91	  // alle Fenster-Schritte rechnen (gleiche Laufzeit, unabhängig vom Treffer)
 92	  for (let d = -fenster; d <= fenster; d++) {
 93	    const s = jetzt + d;
 94	    if (gleich(hotp(schluessel, s), c) && s > letzterSchritt && treffer === null) treffer = s;
 95	  }
 96	  return treffer;
 97	}
 98	
 99	/** otpauth-URI für Authenticator-Apps (Google Authenticator, Microsoft Authenticator, 1Password …) */
100	export function otpauthUri({ geheimnis, konto, aussteller = AUSSTELLER }) {
101	  const label = `${encodeURIComponent(aussteller)}:${encodeURIComponent(konto)}`;
102	  return `otpauth://totp/${label}?secret=${geheimnis}&issuer=${encodeURIComponent(aussteller)}&algorithm=SHA1&digits=${STELLEN}&period=${PERIODE_S}`;
103	}
104	
105	// ---------------------------------------------------------------- Wiederherstellungscodes
106	
107	const CODE_ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"; // ohne 0/O/1/I
108	export const ANZAHL_CODES = 10;
109	
110	/** Ein Code: XXXXX-XXXXX (50 Bit) */
111	function einCode() {
112	  const b = randomBytes(10);
113	  let s = "";
114	  for (let i = 0; i < 10; i++) s += CODE_ALPHABET[b[i] % 32];
115	  return `${s.slice(0, 5)}-${s.slice(5)}`;
116	}
117	
118	export const codesErzeugen = (anzahl = ANZAHL_CODES) => Array.from({ length: anzahl }, einCode);
119	export const codeNormal = (c) => String(c || "").toUpperCase().replace(/[^0-9A-Z]/g, "");
120	export const codeHash = (c) => createHash("sha256").update(`oekoinvest-wiederherstellung|${codeNormal(c)}`).digest("hex");
121	export const istWiederherstellungscode = (c) => /^[0-9A-Z]{10}$/.test(codeNormal(c));
122	
123	// ---------------------------------------------------------------- Verschlüsselung (Demo-Backend)
124	
125	function schluesselMaterial() {
126	  const s = process.env.PLATTFORM_2FA_SCHLUESSEL || process.env.SESSION_SECRET || "";
127	  if (process.env.NODE_ENV === "production" && s.length < 32) {
128	    throw new Error("PLATTFORM_2FA_SCHLUESSEL (oder SESSION_SECRET) fehlt – in Produktion Pflicht für die Zwei-Faktor-Anmeldung.");
129	  }
130	  return createHash("sha256").update(`oekoinvest-2fa|${s || "oekoinvest-entwicklung-unsicher-nie-produktiv-verwenden"}`).digest();
131	}
132	
133	/** Text → "v1.<iv>.<tag>.<chiffrat>" (base64url) */
134	export function verschluesseln(text) {
135	  const iv = randomBytes(12);
136	  const c = createCipheriv("aes-256-gcm", schluesselMaterial(), iv);
137	  const ct = Buffer.concat([c.update(String(text), "utf8"), c.final()]);
138	  return ["v1", iv.toString("base64url"), c.getAuthTag().toString("base64url"), ct.toString("base64url")].join(".");
139	}
140	
141	export function entschluesseln(wert) {
142	  const [v, iv, tag, ct] = String(wert || "").split(".");
143	  if (v !== "v1" || !iv || !tag || !ct) return "";
144	  try {
145	    const d = createDecipheriv("aes-256-gcm", schluesselMaterial(), Buffer.from(iv, "base64url"));
146	    d.setAuthTag(Buffer.from(tag, "base64url"));
147	    return Buffer.concat([d.update(Buffer.from(ct, "base64url")), d.final()]).toString("utf8");
148	  } catch {
149	    return "";
150	  }
151	}
152	// src/lib/plattform/hashkette.js
153	//
154	// Revisionssicheres Aktivitätsprotokoll: Hash-Kette über alle Einträge.
155	//
156	//   hash_n = SHA-256( prevHash_n + "\n" + inhalt_n )      mit prevHash_n = hash_(n-1)
157	//
158	// `inhalt` ist eine kanonische JSON-Darstellung der fachlichen Felder in fester Reihenfolge
159	// (id, am, nutzerId, aktion, objektArt, objektId, text, ip). Wer einen Eintrag nachträglich ändert,
160	// löscht, einfügt oder umsortiert, bricht die Kette ab dieser Stelle – verifyChain() meldet die
161	// erste Abweichung. Identisches Verfahren in Frappe: plattform/hashkette.py (Feld prev_hash/entry_hash).
162	//
163	// Werden alte Einträge archiviert (Demo: > 5000 Einträge), bleibt ein Anker { hash, anzahl, bis }
164	// stehen: die Prüfung beginnt dann beim Anker-Hash statt beim Startwert.
165	//
166	// Nur serverseitig (node:crypto).
167	
168	import { createHash } from "node:crypto";
169	
170	export const KETTE_START = "0".repeat(64);
171	export const KETTE_FELDER = ["id", "am", "nutzerId", "aktion", "objektArt", "objektId", "text", "ip"];
172	
173	const wert = (v) => (v === undefined || v === null ? "" : String(v));
174	
175	/** Kanonischer Inhalt eines Eintrags (unabhängig von zusätzlichen Feldern wie `nutzer`) */
176	export function eintragInhalt(e) {
177	  return JSON.stringify(KETTE_FELDER.map((k) => [k, wert(e?.[k])]));
178	}
179	
180	export function eintragHash(prevHash, e) {
181	  return createHash("sha256").update(`${prevHash}\n${eintragInhalt(e)}`, "utf8").digest("hex");
182	}
183	
184	/** Eintrag an die Kette anhängen: setzt prevHash und hash (verändert das Objekt) */
185	export function verketten(e, prevHash = KETTE_START) {
186	  e.prevHash = prevHash || KETTE_START;
187	  e.hash = eintragHash(e.prevHash, e);
188	  return e;
189	}
190	
191	/**
192	 * Kette prüfen. `eintraege` in Einfügereihenfolge (älteste zuerst).
193	 * Liefert { ok, geprueft, fehler: [{ index, id, grund }], letzterHash, start }.
194	 * Mit `alleFehler: false` (Standard) endet die Prüfung beim ersten Bruch.
195	 */
196	export function verifyChain(eintraege = [], { anker = null, alleFehler = false } = {}) {
197	  const start = anker?.hash || KETTE_START;
198	  let prev = start;
199	  const fehler = [];
200	  let geprueft = 0;
201	  for (let i = 0; i < eintraege.length; i++) {
202	    const e = eintraege[i];
203	    geprueft++;
204	    let grund = "";
205	    if (!e?.hash) grund = "Eintrag ohne Hash (ungesichert eingefügt)";
206	    else if (e.prevHash !== prev) grund = "Verweis auf den Vorgänger passt nicht (Eintrag gelöscht, eingefügt oder umsortiert)";
207	    else if (eintragHash(prev, e) !== e.hash) grund = "Inhalt wurde nachträglich verändert";
208	    if (grund) {
209	      fehler.push({ index: i, id: e?.id || null, am: e?.am || null, grund });
210	      if (!alleFehler) break;
211	    }
212	    prev = e?.hash || prev;
213	  }
214	  return { ok: fehler.length === 0, geprueft, anzahl: eintraege.length, fehler, letzterHash: prev, start };
215	}
216	
217	/** Python-Name wie in Frappe (plattform/hashkette.py) */
218	export const verify_chain = verifyChain;

