190	/** Erwartete Jahreserzeugung in kWh (Region × kWp × Bauart × Alterung) */
191	export function prognoseJahrKwh(a, jahr = new Date().getFullYear()) {
192	  const kwp = Number(a?.kwp) || 0;
193	  if (!kwp) return 0;
194	  const region = regionById(a.regionId || regionFuer(a.land, a.bundesland));
195	  const ibnJahr = Number(String(a.inbetriebnahme || "").slice(0, 4)) || jahr;
196	  const alter = Math.max(0, jahr - ibnJahr);
197	  return kwp * region.ertrag * bauartFaktor(a.typ) * (1 - 0.005) ** alter;
198	}
