209	/**
210	 * Kosten des Kunden aus dem Contracting-Vertrag für einen Zeitraum:
211	 * PV-Strom vor Ort (Eigenverbrauch) × Arbeitspreis + Grundgebühr je Monat.
212	 * Ersparnis = Eigenverbrauch × (Netzstrompreis − Arbeitspreis) − Grundgebühr.
213	 */
214	export function vertragKosten(vertrag, { eigenverbrauchKwh = 0, monate = 1 } = {}) {
215	  if (!vertrag) return null;
216	  const arbeit = (eigenverbrauchKwh * (Number(vertrag.strompreisCt) || 0)) / 100;
217	  const grund = (Number(vertrag.grundgebuehrMonat) || 0) * monate;
218	  const netz = (eigenverbrauchKwh * NETZSTROM_CT) / 100;
219	  return { arbeitEur: arbeit, grundEur: grund, gesamtEur: arbeit + grund, netzEur: netz, ersparnisEur: netz - arbeit - grund };
