228	export function ampelBerechnen({ anlage, live, stoerungen = [], erwartetKw = null, jetzt = Date.now() }) {
229	  if (anlage && anlage.status !== "betrieb") return { id: "offline", grund: ANLAGE_STATUS[anlage.status]?.label || "Nicht in Betrieb" };
230	  const offen = stoerungen.filter((s) => STOERUNG_OFFEN.includes(s.status));
231	  const maxStufe = offen.reduce((m, s) => Math.max(m, STOERUNG_SCHWERE[s.schwere]?.stufe ?? 0), -1);
232	  const alterMin = live?.ts ? (jetzt - new Date(live.ts).getTime()) / 60000 : Infinity;
233	  if (!Number.isFinite(alterMin) || alterMin > GRENZWERTE.offlineMinuten) return { id: "offline", grund: live?.ts ? "Keine Messwerte seit über 15 Minuten" : "Noch keine Messwerte" };
234	  if (maxStufe >= 3 || live?.wechselrichterStatus === "stoerung" || live?.fehlercode) return { id: "stoerung", grund: live?.fehlercode ? `Fehlercode ${live.fehlercode}` : offen[0]?.titel || "Offene Störung" };
235	  const kwp = Number(anlage?.kwp) || 0;
236	  const sonne = erwartetKw != null && kwp > 0 && erwartetKw >= kwp * GRENZWERTE.sonneMinAnteil;
237	  if (sonne && Number(live?.pvKw) < erwartetKw * GRENZWERTE.minderleistungQuote) return { id: "warnung", grund: "Leistung deutlich unter Erwartung" };
238	  if (maxStufe >= 1 || live?.wechselrichterStatus === "warnung") return { id: "warnung", grund: offen[0]?.titel || "Warnung am Wechselrichter" };
