314	/**
315	 * Mindestabnahme (Take-or-Pay) anteilig für einen Zeitraum: Menge, Ist und Fehlmenge × Arbeitspreis (Ausgleich).
316	 * Liefert null ohne Mindestabnahme im Vertrag.
317	 */
318	export function mindestabnahme(vertrag, { eigenverbrauchKwh = 0, monate = 12 } = {}) {
319	  const jahr = Number(vertrag?.mindestabnahmeKwhJahr) || 0;
320	  if (!jahr) return null;
321	  const soll = (jahr * monate) / 12;
322	  const fehl = Math.max(0, soll - (Number(eigenverbrauchKwh) || 0));
323	  return { sollKwh: soll, istKwh: Number(eigenverbrauchKwh) || 0, quote: soll ? (Number(eigenverbrauchKwh) || 0) / soll : null, fehlKwh: fehl, ausgleichEur: (fehl * (Number(vertrag.strompreisCt) || 0)) / 100 };
324	}

