 92	function zugriff(db, n, a) {
 93	  if (!n || !a) return null;
 94	  if (boLesen(n)) return "backoffice";
 95	  if (a.kundeId && a.kundeId === n.id) return "kunde";
 96	  const r = a.organisationId ? teamRolle(db, n.id, a.organisationId) : null;
 97	  if (r) return darfTeamSchreiben(r) ? "team-schreiben" : "team-lesen";
 98	  return null;
