135	function stoerungAusgabe(db, n, s, zg) {
136	  const a = db.anlagen.anlagen.find((x) => x.id === s.anlageId);
137	  const bo = zg === "backoffice";
138	  const z = s.zustaendigId ? nutzerById(db, s.zustaendigId) : null;
139	  const alterH = (Date.now() - new Date(s.erkanntAm).getTime()) / 3600e3;
140	  const stufe = STOERUNG_SCHWERE[s.schwere]?.stufe ?? 0;
141	  return {
142	    id: s.id, anlageId: s.anlageId, anlage: a ? { id: a.id, name: a.name, typ: a.typ, ort: a.ort } : null,
143	    regel: s.regel, regelLabel: STOERUNG_REGELN[s.regel]?.label || s.regel, schwere: s.schwere, schwereLabel: STOERUNG_SCHWERE[s.schwere]?.label || s.schwere,
144	    titel: s.titel, text: s.text, status: s.status, statusLabel: STOERUNG_STATUS[s.status]?.label || s.status,
145	    erkanntAm: s.erkanntAm, zuletztAm: s.zuletztAm || s.erkanntAm, anzahl: s.anzahl || 1, behobenAm: s.behobenAm || null,
146	    quittiert: !!s.quittiertAm, quittiertAm: s.quittiertAm || null, quittiertVon: s.quittiertVon ? nameVon(db, s.quittiertVon) : null,
147	    zustaendig: z ? { id: z.id, name: nameVon(db, z.id) } : null,
148	    // Priorität: Schwere zuerst, dann Alter (je 6 h ein Punkt, gedeckelt), unquittiert +2
149	    prioritaet: STOERUNG_OFFEN.includes(s.status) ? stufe * 10 + Math.min(8, Math.floor(alterH / 6)) + (s.quittiertAm ? 0 : 2) : 0,
150	    kommentare: (s.kommentare || []).filter((k) => bo || !k.intern).map((k) => ({ id: k.id, vonName: k.backoffice && !bo ? "ÖkoInvest Betrieb" : k.vonName, backoffice: !!k.backoffice, am: k.am, text: k.text, intern: !!k.intern })),
151	    verlauf: bo ? s.verlauf || [] : undefined,
152	    darfKommentieren: bo ? boSchreiben(n) : zg === "kunde" || zg === "team-schreiben",
153	    darfBearbeiten: boSchreiben(n),
154	  };
