164	    inbetriebnahme: a.inbetriebnahme, lastprofil: a.lastprofil, lastJahrKwh: a.lastJahrKwh, wechselrichterAnzahl: a.wechselrichterAnzahl, beschreibung: a.beschreibung || "",
165	    // Demo: Szenario des Simulators (offline, Teilausfall, Minderleistung) – Frappe kennt das Feld nicht
