170	    dachgeber: a.dachgeberIstKunde ? (orgName(db, a.organisationId) || kundeAusgabe(db, a).kunde?.firma || "Stromabnehmer") : a.dachgeber || "", dachgeberIstKunde: !!a.dachgeberIstKunde,
