172	    dienstbarkeitDatum: a.dienstbarkeitDatum || "", dienstbarkeitDokumentId: a.dienstbarkeitDokumentId || null, dienstbarkeitHinweis: a.dienstbarkeitHinweis || "",
173	    finanziertDurch: zg === "backoffice" ? a.finanziertDurch || "" : undefined,
174	    offeneStoerungen: offen.map((s) => ({ id: s.id, schwere: s.schwere, status: s.status, titel: s.titel, regel: s.regel })),
175	    vertrag: vertrag ? { strompreisCt: vertrag.strompreisCt, grundgebuehrMonat: vertrag.grundgebuehrMonat, status: vertrag.status } : null,
176	    meinZugriff: zg,
