183	    ...basis,
184	    vertrag: vertragAusgabe(vertrag),
185	    // Technische Tiefe (Komponenten, Monitoring-Messpunkte) nur fürs Backoffice; Kunden sehen die abrechnungsrelevanten Zähler
186	    komponenten: bo ? db.anlagen.komponenten.filter((k) => k.anlageId === a.id).map((k) => ({ ...k, artLabel: KOMPONENTEN_ARTEN[k.art] || k.art })) : undefined,
187	    messpunkte: db.anlagen.messpunkte.filter((m) => m.anlageId === a.id && (bo || m.abrechnungsrelevant)).map((m) => ({ ...m, artLabel: MESSPUNKT_ARTEN[m.art]?.label || m.art, messstelleLabel: MESSSTELLEN[m.messstelle] || m.messstelle })),
