232	function anlageFelder(db, d, alt = {}) {
233	  const has = (k) => Object.hasOwn(d, k);
234	  const f = {};
235	  if (has("name") || !alt.id) f.name = v.text(d.name, 120);
236	  if (has("typ") || !alt.id) f.typ = v.auswahl(d.typ, ANLAGE_TYPEN, alt.typ || "");
237	  if (has("status") || !alt.id) f.status = v.auswahl(d.status, ANLAGE_STATUS, alt.status || "betrieb");
238	  if (has("land") || !alt.id) f.land = v.auswahl(d.land, LAENDER, alt.land || "DE");
239	  const land = f.land || alt.land;
240	  if (has("bundesland") || !alt.id) f.bundesland = v.auswahl(d.bundesland, BUNDESLAENDER[land] || [], "");
241	  if (has("ort")) f.ort = v.text(d.ort, 80);
242	  for (const [k, max] of [["kwp", 500000], ["speicherKwh", 1000000], ["speicherKw", 500000], ["lastJahrKwh", 1e9]]) {
243	    if (has(k)) f[k] = v.zahl(d[k], { min: 0, max, stellen: 1 }) ?? 0;
244	  }
245	  if (has("wechselrichterAnzahl")) f.wechselrichterAnzahl = Math.round(v.zahl(d.wechselrichterAnzahl, { min: 1, max: 999 }) ?? 1);
246	  if (has("lastprofil") || !alt.id) f.lastprofil = v.auswahl(d.lastprofil, LASTPROFILE, alt.lastprofil || "gewerbe");
247	  if (has("inbetriebnahme")) f.inbetriebnahme = /^20\d\d-\d\d-\d\d$/.test(String(d.inbetriebnahme || "")) ? d.inbetriebnahme : "";
248	  if (has("beschreibung")) f.beschreibung = v.mehrzeilig(d.beschreibung, 2000);
249	  if (has("kundeId")) {
250	    const k = v.kennung(d.kundeId);
251	    if (k && !nutzerById(db, k)) throw ungueltig("Kundenkonto nicht gefunden.");
252	    f.kundeId = k || null;
253	  }
254	  if (has("organisationId")) {
255	    const o = v.kennung(d.organisationId);
256	    if (o && !(db.organisationen || []).some((x) => x.id === o)) throw ungueltig("Organisation nicht gefunden.");
257	    f.organisationId = o || null;
258	  }
259	  // Eigentum & Betrieb (Pflicht: Eigentümergesellschaft – ÖkoInvest GmbH oder Projektgesellschaft/SPV)
260	  if (has("eigentuemer") || !alt.id) f.eigentuemer = v.text(d.eigentuemer, 160);
261	  if (has("eigentuemerId")) {
262	    // Gesellschaftsverzeichnis (db.dienste.gesellschaften, Team Dienste): Kennung prüfen, Name übernehmen
263	    f.eigentuemerId = v.kennung(d.eigentuemerId) || null;
264	    if (f.eigentuemerId) {
265	      const g = (db.dienste?.gesellschaften || []).find((x) => x.id === f.eigentuemerId);
266	      if (!g) throw ungueltig("Gesellschaft nicht im Gesellschaftsverzeichnis gefunden.");
267	      f.eigentuemer = g.name;
268	    }
