585	  if (schluessel && db.anlagen.stoerungen.some((s) => s.schluessel === schluessel)) return { stoerung: null, neu: false };
586	  const t = jetzt();
587	  const s = {
588	    id: neueId("ST"), anlageId, geraetId, regel: v.auswahl(regel, STOERUNG_REGELN, "manuell"), schwere: v.auswahl(schwere, STOERUNG_SCHWERE, STOERUNG_REGELN[regel]?.schwere || "mittel"),
589	    titel: v.text(titel, 140) || STOERUNG_REGELN[regel]?.label || "Störung", text: v.mehrzeilig(text, 2000), status: "offen", erkanntAm: t, zuletztAm: t, anzahl: 1,
590	    quittiertAm: null, quittiertVon: null, zustaendigId: null, behobenAm: null, kommentare: [], verlauf: [{ am: t, text: von ? `Manuell erfasst von ${nameVon(db, von)}` : "Störung erkannt" }], schluessel,
591	  };
592	  db.anlagen.stoerungen.push(s);
593	  if (db.anlagen.stoerungen.length > 5000) {
594	    const idx = db.anlagen.stoerungen.findIndex((x) => x.status === "behoben");
595	    if (idx >= 0) db.anlagen.stoerungen.splice(idx, 1);
