  1	// src/lib/plattform/backend/demo/service-tickets.js
  2	//
  3	// Service & Support (Tickets mit SLA) im Demo-Backend – Referenz für plattform/api/support.py (docs/API.md, Abschnitt „Dokumente, Signatur, Termine, Service & HR“).
  4	// Ohne Frappe Helpdesk die eigene, schlanke Ticket-Logik; mit Helpdesk spiegelt Frappe nach „HD Ticket“.
  5	//
  6	// Rechte:
  7	//   Kunde         – eigene Tickets (kontoId) bzw. Tickets der Organisation (Teamrolle ≥ lesen; schreiben ab „Mitglied“);
  8	//                   eröffnen, antworten, Anhänge, als gelöst markieren. Sieht nie interne Notizen und keine SLA-Interna.
  9	//   Backoffice    – Bereich „support“: lesen ≥ 1 alle Tickets; schreiben = 2 antworten, interne Notizen, Status, Priorität,
 10	//                   Zuweisung, Ticket aus Anlagen-Störung (Unterrollen leitung, betrieb).
 11	//   sonst         – 403 (Seiten 404)
 12	
 13	import { PlattformFehler, konflikt, nichtGefunden, verboten } from "../../fehler";
 14	import * as v from "../../validierung";
 15	import {
 16	  PRIORITAET_AUS_SCHWERE, TICKET_GRENZEN, TICKET_KATEGORIEN, TICKET_KATEGORIE_IDS, TICKET_OFFEN, TICKET_PRIORITAETEN, TICKET_PRIORITAET_IDS, TICKET_STATUS,
 17	  slaFristen, slaStand,
 18	} from "../../tickets";
 19	import { vertretungFinden } from "../../hr";
 20	import { heuteTag } from "../../termine";
 21	import { darfSchreiben } from "../../rechte";
 22	import { jetzt, neueId, sha256 } from "./hilfen";
 23	import { darfTeamLesenObjekt, darfTeamSchreibenObjekt, organisationFuerNeu } from "./teams";
 24	import { angemeldet, aendernBereit, backofficeKonten, boLesen, boSchreiben, dateiLesen, dateiSchreiben, kontoKurz, lesenBereit, melden, nameVon, nutzerById, protokoll, schreibNoetig } from "./service-kern";
 25	
 26	const BEREICH = "support";
 27	const LABEL = "Service & Support";
 28	
 29	function zugriff(db, n, t) {
 30	  if (!n || !t) return null;
 31	  if (boLesen(n, BEREICH)) return "backoffice";
 32	  if (t.kontoId === n.id) return "kunde";
 33	  if (darfTeamSchreibenObjekt(db, n, t)) return "team-schreiben";
 34	  if (darfTeamLesenObjekt(db, n, t)) return "team-lesen";
 35	  return null;
 36	}
 37	
 38	function laden(db, n, id) {
 39	  angemeldet(n);
 40	  const t = db.service.tickets.find((x) => x.id === v.kennung(id));
 41	  if (!t) throw nichtGefunden("Ticket nicht gefunden.");
 42	  if (!zugriff(db, n, t)) throw verboten("Dieses Ticket gehört nicht zu Ihrem Konto.");
 43	  return t;
 44	}
 45	
 46	function ausgabe(db, n, t, { detail = false } = {}) {
 47	  const zg = zugriff(db, n, t);
 48	  const bo = zg === "backoffice";
 49	  const sla = slaStand(t);
 50	  const anlage = t.anlageId ? (db.anlagen?.anlagen || []).find((a) => a.id === t.anlageId) : null;
 51	  const basis = {
 52	    id: t.id, betreff: t.betreff, kategorie: t.kategorie, kategorieLabel: TICKET_KATEGORIEN[t.kategorie]?.label || t.kategorie,
 53	    prioritaet: t.prioritaet, prioritaetLabel: TICKET_PRIORITAETEN[t.prioritaet]?.label || t.prioritaet,
 54	    status: t.status, statusLabel: TICKET_STATUS[t.status]?.label || t.status, offen: TICKET_OFFEN.includes(t.status),
 55	    anlage: anlage ? { id: anlage.id, name: anlage.name } : null, stoerungId: t.stoerungId || null,
 56	    kunde: bo ? kontoKurz(db, t.kontoId) : undefined,
 57	    zustaendig: t.zustaendigId ? (bo ? kontoKurz(db, t.zustaendigId) : { name: nameVon(db, t.zustaendigId) }) : null,
 58	    sla: bo ? sla : { ampel: sla.ampel === "verletzt" || sla.ampel === "warn" ? "ok" : sla.ampel, reaktionBis: t.slaReaktionBis, geantwortet: !!t.ersteReaktionAm },
 59	    antworten: t.nachrichten.filter((m) => bo || !m.intern).length,
 60	    ungelesen: bo ? !t.gelesenBackoffice : !t.gelesenKunde,
 61	    erstelltAm: t.erstelltAm, geaendertAm: t.geaendertAm, helpdesk: bo ? t.helpdesk || null : undefined,
 62	    meinZugriff: zg,
 63	    darfAntworten: bo ? boSchreiben(n, BEREICH) : zg === "kunde" || zg === "team-schreiben",
 64	    darfBearbeiten: boSchreiben(n, BEREICH),
 65	  };
 66	  if (!detail) return basis;
 67	  return {
 68	    ...basis,
 69	    nachrichten: t.nachrichten.filter((m) => bo || !m.intern).map((m) => ({ id: m.id, am: m.am, text: m.text, intern: !!m.intern, backoffice: !!m.backoffice, vonName: m.backoffice && !bo ? `${nameVon(db, m.vonId).split(" ")[0] || "ÖkoInvest"} (ÖkoInvest Service)` : nameVon(db, m.vonId) || "System", ich: m.vonId === n.id })),
 70	    anhaenge: t.anhaenge.map((a) => ({ id: a.id, name: a.name, mime: a.mime, groesse: a.groesse, am: a.am, vonName: nameVon(db, a.vonId) })),
 71	    verlauf: bo ? t.verlauf : undefined,
 72	  };
 73	}
 74	
 75	function verlauf(t, text, n) {
 76	  t.verlauf.push({ am: jetzt(), text: v.text(text, 300), vonId: n?.id || null });
 77	}
 78	
 79	/** Zuständigkeit: Support-Schreibende, abwesende Personen über die Vertretung, sonst die mit den wenigsten offenen Tickets */
 80	function zustaendigWaehlen(db) {
 81	  const kandidaten = backofficeKonten(db).filter((u) => darfSchreiben(u, BEREICH));
 82	  if (!kandidaten.length) return null;
 83	  const offen = (id) => db.service.tickets.filter((t) => t.zustaendigId === id && TICKET_OFFEN.includes(t.status)).length;
 84	  const sortiert = [...kandidaten].sort((a, b) => offen(a.id) - offen(b.id));
 85	  for (const u of sortiert) {
 86	    const z = vertretungFinden({ mitarbeiterId: u.id, tag: heuteTag(), abwesenheiten: db.service.abwesenheiten, mitarbeiter: db.service.mitarbeiter });
 87	    if (z) return z.id;
 88	  }
 89	  return sortiert[0].id;
 90	}
 91	
 92	function ticketErzeugen(db, n, { betreff, kategorie, prioritaet, text, kontoId, organisationId = null, anlageId = null, stoerungId = null, herkunft = "portal" }) {
 93	  const erstellt = jetzt();
 94	  const frist = slaFristen(prioritaet, erstellt);
 95	  const t = {
 96	    id: neueId("TK"), betreff, kategorie, prioritaet, status: "neu", kontoId, organisationId, anlageId, stoerungId, herkunft,
 97	    zustaendigId: zustaendigWaehlen(db), slaReaktionBis: frist.reaktionBis, slaLoesungBis: frist.loesungBis,
 98	    ersteReaktionAm: null, geloestAm: null, nachrichten: [], anhaenge: [], verlauf: [], erstelltAm: erstellt, geaendertAm: erstellt,
 99	    gelesenKunde: true, gelesenBackoffice: false, helpdesk: null,
100	  };
101	  if (text) t.nachrichten.push({ id: neueId("TN"), am: erstellt, vonId: n?.id || null, backoffice: herkunft === "stoerung", intern: false, text });
102	  verlauf(t, `Ticket eröffnet (${TICKET_KATEGORIEN[kategorie]?.label}, ${TICKET_PRIORITAETEN[prioritaet]?.label})`, n);
103	  db.service.tickets.push(t);
104	  if (t.zustaendigId) melden(db, t.zustaendigId, { art: "ticket", titel: `Neues Ticket: ${betreff}`, text: `${TICKET_PRIORITAETEN[prioritaet].label} · Reaktion bis ${new Date(t.slaReaktionBis).toLocaleString("de-DE", { timeZone: "Europe/Vienna", dateStyle: "short", timeStyle: "short" })}`, link: `/portal/admin/support?ticket=${t.id}`, objektArt: "ticket", objektId: t.id });
105	  if (kontoId && kontoId !== n?.id) melden(db, kontoId, { art: "ticket", titel: `Ticket eröffnet: ${betreff}`, text: "Wir kümmern uns darum.", link: `/portal/support/${t.id}`, objektArt: "ticket", objektId: t.id });
106	  return t;
107	}
108	
109	// ================================================================ Lesen
110	
111	export async function tickets(n, { status = "", alle = false, q = "" } = {}) {
112	  angemeldet(n);
113	  const db = await lesenBereit();
114	  const bo = boLesen(n, BEREICH);
115	  const such = v.text(q, 80).toLowerCase();
116	  return db.service.tickets
117	    .filter((t) => (alle && bo ? true : t.kontoId === n.id || darfTeamLesenObjekt(db, n, t)))
118	    .filter((t) => (status === "offen" ? TICKET_OFFEN.includes(t.status) : status === "erledigt" ? !TICKET_OFFEN.includes(t.status) : !status || t.status === status))
119	    .filter((t) => !such || [t.id, t.betreff, nameVon(db, t.kontoId)].join(" ").toLowerCase().includes(such))
120	    .sort((a, b) => {
121	      if (bo && alle) {
122	        const pa = (TICKET_OFFEN.includes(a.status) ? 10 : 0) + TICKET_PRIORITAETEN[a.prioritaet].stufe;
123	        const pb = (TICKET_OFFEN.includes(b.status) ? 10 : 0) + TICKET_PRIORITAETEN[b.prioritaet].stufe;
124	        if (pa !== pb) return pb - pa;
125	      }
126	      return String(b.geaendertAm).localeCompare(String(a.geaendertAm));
127	    })
128	    .slice(0, 500)
129	    .map((t) => ausgabe(db, n, t));
130	}
131	
132	export async function ticket(n, id, { markieren = true } = {}) {
133	  const db0 = await lesenBereit();
134	  const t0 = laden(db0, n, id);
135	  const bo = zugriff(db0, n, t0) === "backoffice";
136	  if (markieren && ((bo && !t0.gelesenBackoffice) || (!bo && !t0.gelesenKunde))) {
137	    return aendernBereit((db) => {
138	      const t = laden(db, n, id);
139	      if (bo) t.gelesenBackoffice = true;
140	      else t.gelesenKunde = true;
141	      return ausgabe(db, n, t, { detail: true });
142	    });
143	  }
144	  return ausgabe(db0, n, t0, { detail: true });
145	}
