147	// ================================================================ Anlegen & Antworten
148	
149	export async function ticketAnlegen(n, daten = {}, { anlagePruefen } = {}) {
150	  angemeldet(n);
151	  const betreff = v.text(daten.betreff, TICKET_GRENZEN.betreff);
152	  v.pflicht(betreff.length >= 4, "Bitte geben Sie einen Betreff an (mind. 4 Zeichen).");
153	  const text = v.mehrzeilig(daten.text, TICKET_GRENZEN.text);
154	  v.pflicht(text.length >= 10, "Bitte beschreiben Sie Ihr Anliegen (mind. 10 Zeichen).");
155	  const kategorie = v.auswahl(daten.kategorie, TICKET_KATEGORIE_IDS, "sonstiges");
156	  const bo = boSchreiben(n, BEREICH);
157	  // Kunden wählen höchstens „hoch“ – „kritisch“ setzt das Backoffice (bzw. die Störungs-Übernahme)
158	  const prioritaet = v.auswahl(daten.prioritaet, bo ? TICKET_PRIORITAET_IDS : ["niedrig", "normal", "hoch"], kategorie === "stoerung" ? "hoch" : "normal");
159	  let anlageId = null;
160	  if (daten.anlageId) {
161	    // Zugriff auf die Anlage vorab über das Anlagen-Modul (fremde Anlage → 403)
162	    if (anlagePruefen) await anlagePruefen(v.kennung(daten.anlageId));
163	    anlageId = v.kennung(daten.anlageId);
164	  }
165	  return aendernBereit((db) => {
166	    const kontoId = bo && daten.fuerKontoId ? nutzerById(db, v.kennung(daten.fuerKontoId))?.id || null : n.id;
167	    if (bo && daten.fuerKontoId && !kontoId) throw nichtGefunden("Konto nicht gefunden.");
168	    const organisationId = bo ? null : organisationFuerNeu(db, n);
169	    const t = ticketErzeugen(db, n, { betreff, kategorie, prioritaet, text, kontoId, organisationId, anlageId, herkunft: bo ? "backoffice" : "portal" });
170	    protokoll(db, n, "ticket", "ticket", t.id, `Ticket „${betreff}“ eröffnet`);
171	    return ausgabe(db, n, t, { detail: true });
172	  });
173	}
174	
175	export async function ticketAntworten(n, id, { text, intern = false } = {}) {
176	  angemeldet(n);
177	  const inhalt = v.mehrzeilig(text, TICKET_GRENZEN.text);
178	  v.pflicht(inhalt.length >= 2, "Bitte geben Sie eine Nachricht ein.");
179	  return aendernBereit((db) => {
180	    const t = laden(db, n, id);
181	    const zg = zugriff(db, n, t);
182	    const bo = zg === "backoffice";
183	    if (bo && !boSchreiben(n, BEREICH)) throw verboten("Ihre Backoffice-Rolle erlaubt im Bereich „Service & Support“ kein Schreiben.");
184	    if (!bo && zg === "team-lesen") throw verboten("Mit der Rolle „Nur lesen“ können Sie nicht antworten.");
185	    if (t.status === "geschlossen") throw konflikt("Das Ticket ist geschlossen. Bitte eröffnen Sie ein neues Ticket.");
186	    const istIntern = bo && v.wahr(intern);
187	    t.nachrichten.push({ id: neueId("TN"), am: jetzt(), vonId: n.id, backoffice: bo, intern: istIntern, text: inhalt });
188	    t.geaendertAm = jetzt();
189	    if (bo && !istIntern) {
190	      if (!t.ersteReaktionAm) t.ersteReaktionAm = jetzt();
191	      if (t.status === "neu") t.status = "in_arbeit";
192	      t.gelesenKunde = false;
193	      melden(db, t.kontoId, { art: "ticket", titel: `Antwort zu: ${t.betreff}`, text: "Das Service-Team hat geantwortet.", link: `/portal/support/${t.id}`, objektArt: "ticket", objektId: t.id });
194	    } else if (!bo) {
195	      if (["wartet_kunde", "geloest"].includes(t.status)) {
196	        verlauf(t, "Wieder geöffnet durch Antwort des Kunden", n);
197	        t.status = "in_arbeit";
198	        t.geloestAm = null;
199	      }
200	      t.gelesenBackoffice = false;
201	      if (t.zustaendigId) melden(db, t.zustaendigId, { art: "ticket", titel: `Kundenantwort: ${t.betreff}`, text: nameVon(db, n.id), link: `/portal/admin/support?ticket=${t.id}`, objektArt: "ticket", objektId: t.id }, { mail: false });
202	    }
203	    return ausgabe(db, n, t, { detail: true });
204	  });
205	}
206	
207	export async function ticketAktion(n, id, { aktion, status, prioritaet, zustaendigId } = {}) {
208	  angemeldet(n);
209	  return aendernBereit((db) => {
210	    const t = laden(db, n, id);
211	    const zg = zugriff(db, n, t);
212	    if (zg !== "backoffice") {
213	      // Kunde: nur „gelöst“ bestätigen bzw. schließen
214	      if (zg === "team-lesen") throw verboten("Mit der Rolle „Nur lesen“ können Sie das Ticket nicht ändern.");
215	      if (aktion !== "schliessen") throw verboten("Diese Änderung kann nur das Service-Team vornehmen.");
216	      if (!TICKET_OFFEN.includes(t.status) && t.status !== "geloest") throw konflikt("Das Ticket ist bereits geschlossen.");
217	      t.status = "geschlossen";
218	      t.geloestAm = t.geloestAm || jetzt();
219	      verlauf(t, "Vom Kunden geschlossen", n);
220	      t.geaendertAm = jetzt();
221	      return ausgabe(db, n, t, { detail: true });
222	    }
223	    schreibNoetig(n, BEREICH, LABEL);
224	    if (aktion === "status") {
225	      const st = v.auswahl(status, TICKET_STATUS, "");
226	      v.pflicht(st, "Unbekannter Status.");
227	      if (st === t.status) return ausgabe(db, n, t, { detail: true });
228	      verlauf(t, `Status: ${TICKET_STATUS[t.status].label} → ${TICKET_STATUS[st].label}`, n);
229	      t.status = st;
230	      if (st === "geloest") t.geloestAm = jetzt();
231	      if (TICKET_OFFEN.includes(st)) t.geloestAm = null;
232	      if (st !== "neu" && !t.ersteReaktionAm) t.ersteReaktionAm = jetzt();
233	      melden(db, t.kontoId, { art: "ticket", titel: `${TICKET_STATUS[st].label}: ${t.betreff}`, text: st === "geloest" ? "Bitte prüfen Sie die Lösung – mit einer Antwort öffnen Sie das Ticket wieder." : "Der Status Ihres Tickets hat sich geändert.", link: `/portal/support/${t.id}`, objektArt: "ticket", objektId: t.id }, { mail: st === "geloest" || st === "wartet_kunde" });
234	    } else if (aktion === "prioritaet") {
235	      const p = v.auswahl(prioritaet, TICKET_PRIORITAET_IDS, "");
236	      v.pflicht(p, "Unbekannte Priorität.");
237	      const f = slaFristen(p, t.erstelltAm);
238	      verlauf(t, `Priorität: ${TICKET_PRIORITAETEN[t.prioritaet].label} → ${TICKET_PRIORITAETEN[p].label} (SLA neu berechnet)`, n);
239	      Object.assign(t, { prioritaet: p, slaReaktionBis: f.reaktionBis, slaLoesungBis: f.loesungBis });
240	    } else if (aktion === "zuweisen") {
241	      const z = nutzerById(db, v.kennung(zustaendigId));
242	      v.pflicht(z && z.aktiv && z.rollen.includes("admin"), "Zuständig kann nur ein aktives Backoffice-Konto sein.");
243	      t.zustaendigId = z.id;
244	      verlauf(t, `Zugewiesen an ${nameVon(db, z.id)}`, n);
245	      if (z.id !== n.id) melden(db, z.id, { art: "ticket", titel: `Ticket zugewiesen: ${t.betreff}`, text: `Von ${nameVon(db, n.id)}`, link: `/portal/admin/support?ticket=${t.id}`, objektArt: "ticket", objektId: t.id });
246	    } else throw new PlattformFehler(422, "Unbekannte Aktion.");
247	    t.geaendertAm = jetzt();
248	    protokoll(db, n, "ticket", "ticket", t.id, `Ticket ${aktion}`);
249	    return ausgabe(db, n, t, { detail: true });
250	  });
251	}
