 44	/** SLA-Fristen beim Anlegen (ISO) */
 45	export function slaFristen(prioritaet, erstelltAm = new Date().toISOString()) {
 46	  const p = TICKET_PRIORITAETEN[prioritaet] || TICKET_PRIORITAETEN.normal;
 47	  const t = new Date(erstelltAm).getTime();
 48	  return { reaktionBis: new Date(t + p.reaktionH * 3600e3).toISOString(), loesungBis: new Date(t + p.loesungH * 3600e3).toISOString() };
 49	}
 50	
 51	/**
 52	 * SLA-Stand eines Tickets: je Frist { bis, erfuellt, verletzt, restMin } und Ampel ok | warn | verletzt | erledigt.
 53	 * Warnung ab 25 % Restzeit. „Wartet auf Kunde“ hält die Lösungsfrist NICHT an (bewusst einfach, dokumentiert).
 54	 */
 55	export function slaStand(t, jetzt = Date.now()) {
 56	  const pruef = (bis, erfuelltAm, gesamtH) => {
 57	    const b = new Date(bis).getTime();
 58	    if (!Number.isFinite(b)) return null;
 59	    if (erfuelltAm) {
 60	      const e = new Date(erfuelltAm).getTime();
 61	      return { bis, erfuellt: true, verletzt: e > b, restMin: 0 };
 62	    }
 63	    const rest = Math.round((b - jetzt) / 60e3);
 64	    return { bis, erfuellt: false, verletzt: rest < 0, restMin: rest, knapp: rest >= 0 && rest < gesamtH * 60 * 0.25 };
 65	  };
 66	  const p = TICKET_PRIORITAETEN[t.prioritaet] || TICKET_PRIORITAETEN.normal;
 67	  const reaktion = pruef(t.slaReaktionBis, t.ersteReaktionAm, p.reaktionH);
 68	  const loesung = pruef(t.slaLoesungBis, t.geloestAm, p.loesungH);
 69	  const offen = TICKET_OFFEN.includes(t.status);
 70	  let ampel = "ok";
 71	  if (!offen) ampel = reaktion?.verletzt || loesung?.verletzt ? "verletzt" : "erledigt";
 72	  else if (reaktion?.verletzt || loesung?.verletzt) ampel = "verletzt";
 73	  else if (reaktion?.knapp || loesung?.knapp) ampel = "warn";
 74	  return { reaktion, loesung, ampel };
 75	}
