 81	/** Restzeit lesbar: „noch 3 Std.“, „seit 20 Min. überschritten“ */
 82	export function restText(min) {
 83	  if (min === null || min === undefined) return "–";
 84	  const a = Math.abs(min);
 85	  const t = a < 60 ? `${a} Min.` : a < 48 * 60 ? `${Math.round(a / 60)} Std.` : `${Math.round(a / 1440)} Tg.`;
 86	  return min < 0 ? `seit ${t} überschritten` : `noch ${t}`;
 87	}

