 56	export function vertretungFinden({ mitarbeiterId, tag, abwesenheiten = [], mitarbeiter = {} }) {
 57	  const kette = [mitarbeiterId];
 58	  let aktuell = mitarbeiterId;
 59	  for (let i = 0; i <= HR_GRENZEN.vertretungTiefe; i++) {
 60	    const ab = abwesenheitAm(abwesenheiten, aktuell, tag);
 61	    if (!ab && mitarbeiter[aktuell]?.aktiv !== false) return { id: aktuell, kette, grund: i === 0 ? "anwesend" : "vertretung" };
 62	    const naechster = ab?.vertretungId || mitarbeiter[aktuell]?.vertretungId || null;
 63	    if (!naechster || kette.includes(naechster)) return null;
 64	    kette.push(naechster);
 65	    aktuell = naechster;
 66	  }
 67	  return null;
