 74	export function auslastung({ kapazitaetStunden = 38.5, terminMinuten = 0, aufgabenOffen = 0, ticketsOffen = 0, signaturenOffen = 0, abwesendeTage = 0 } = {}) {
 75	  const kap = Math.max(0, kapazitaetStunden * (1 - Math.min(5, abwesendeTage) / 5));
 76	  const last = terminMinuten / 60 + aufgabenOffen * 1 + ticketsOffen * 1.5 + signaturenOffen * 0.25;
 77	  const prozent = kap > 0 ? Math.min(150, Math.round((last / kap) * 100)) : last > 0 ? 150 : 0;
 78	  return { prozent, stundenLast: Math.round(last * 10) / 10, stundenKapazitaet: Math.round(kap * 10) / 10, ampel: prozent >= 100 ? "hoch" : prozent >= 75 ? "mittel" : "frei" };
