 94	    p.stunden = Math.round((p.stunden + Number(z.stunden || 0)) * 100) / 100;
 95	    p.taetigkeiten[z.taetigkeit] = Math.round(((p.taetigkeiten[z.taetigkeit] || 0) + Number(z.stunden || 0)) * 100) / 100;
