100	/** Einfache Volltextsuche (Titel stärker gewichtet) */
101	export function wissenTreffer(artikel, q) {
102	  const worte = String(q || "").toLowerCase().split(/\s+/).filter((w) => w.length >= 2).slice(0, 8);
103	  if (!worte.length) return 1;
104	  const titel = String(artikel.titel || "").toLowerCase();
105	  const text = `${artikel.inhalt || ""} ${(artikel.tags || []).join(" ")}`.toLowerCase();
106	  let punkte = 0;
107	  for (const w of worte) {
108	    if (titel.includes(w)) punkte += 3;
109	    else if (text.includes(w)) punkte += 1;
110	    else return 0;
111	  }
112	  return punkte;
113	}
