185	/** Wandzeit in Europe/Vienna für einen Zeitpunkt (ms) */
186	export function wandzeit(ms) {
187	  const p = Object.fromEntries(teileFormat.formatToParts(new Date(ms)).map((x) => [x.type, x.value]));
188	  const wt = { Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6, Sun: 7 }[p.weekday];
189	  return { tag: `${p.year}-${p.month}-${p.day}`, zeit: `${p.hour}:${p.minute}`, wochentag: wt, jahr: +p.year, monat: +p.month, t: +p.day, h: +p.hour, m: +p.minute, s: +p.second };
190	}
191	
192	/** Wandzeit (Tag "YYYY-MM-DD", Zeit "HH:MM") in Europe/Vienna → UTC-Millisekunden */
193	export function lokalNachUtc(tag, zeit) {
194	  const [j, mo, d] = tag.split("-").map(Number);
195	  const [h, mi] = zeit.split(":").map(Number);
196	  const ziel = Date.UTC(j, mo - 1, d, h, mi);
197	  let ms = ziel;
198	  for (let i = 0; i < 3; i++) {
199	    const w = wandzeit(ms);
200	    const ist = Date.UTC(w.jahr, w.monat - 1, w.t, w.h, w.m);
201	    ms += ziel - ist;
202	  }
203	  return ms;
204	}
