206	/** Wochentag (1 = Mo … 7 = So) eines Kalendertags */
207	export function wochentagVon(tag) {
208	  const d = new Date(`${tag}T12:00:00Z`).getUTCDay();
209	  return d === 0 ? 7 : d;
210	}
