220	/** Arbeitszeiten bereinigen: nur gültige, aufsteigende Fenster, Wochentage 1–7 */
221	export function arbeitszeitenBereinigen(roh) {
222	  const out = {};
223	  for (let wt = 1; wt <= 7; wt++) {
224	    const liste = Array.isArray(roh?.[wt]) ? roh[wt] : [];
225	    const fenster = liste
226	      .filter((f) => Array.isArray(f) && zeitGueltig(f[0]) && zeitGueltig(f[1]) && f[0] < f[1])
227	      .slice(0, 4)
228	      .sort((a, b) => a[0].localeCompare(b[0]));
229	    if (fenster.length) out[wt] = fenster.map((f) => [f[0], f[1]]);
230	  }
231	  return out;
232	}
