234	/** Ist der Kalendertag für den Mitarbeiter gesperrt (Feiertag oder Abwesenheit)? */
235	export function tagGesperrt(tag, { feiertage = [], abwesenheiten = [] } = {}) {
236	  if (feiertage.includes(tag)) return "feiertag";
237	  if (abwesenheiten.some((a) => a.von <= tag && tag <= a.bis)) return "abwesend";
238	  return null;
239	}
