244	/**
245	 * Freie Slots eines Mitarbeiters.
246	 * @param {object} p
247	 *   arbeitszeiten, feiertage [tag], abwesenheiten [{von,bis}], belegt [{start,ende}] (ISO), dauer, puffer (Minuten),
248	 *   vonTag, bisTag, jetzt (ms), vorlaufStunden, raster (Minuten)
249	 * @returns [{ start, ende }] (ISO, UTC)
250	 */
251	export function freieSlots({ arbeitszeiten = ARBEITSZEITEN_STANDARD, feiertage = [], abwesenheiten = [], belegt = [], dauer = 60, puffer = 0, vonTag, bisTag, jetzt = Date.now(), vorlaufStunden = 0, raster = TERMIN_GRENZEN.raster } = {}) {
252	  const slots = [];
253	  const frueh = jetzt + vorlaufStunden * 3600e3;
254	  const belegung = belegt.map((b) => [new Date(b.start).getTime(), new Date(b.ende).getTime()]).filter(([a, e]) => Number.isFinite(a) && Number.isFinite(e));
255	  const az = arbeitszeitenBereinigen(arbeitszeiten);
256	  for (let tag = vonTag, i = 0; tag <= bisTag && i < 100; tag = tagPlus(tag, 1), i++) {
257	    if (tagGesperrt(tag, { feiertage, abwesenheiten })) continue;
258	    for (const [von, bis] of az[wochentagVon(tag)] || []) {
259	      const fensterEnde = lokalNachUtc(tag, bis);
260	      for (let start = lokalNachUtc(tag, von); start + dauer * 60e3 <= fensterEnde; start += raster * 60e3) {
261	        const ende = start + dauer * 60e3;
262	        if (start < frueh) continue;
263	        // Puffer vor und nach dem neuen Termin gegen bestehende Termine
264	        if (belegung.some(([a, e]) => ueberschneidung(start - puffer * 60e3, ende + puffer * 60e3, a, e))) continue;
265	        slots.push({ start: new Date(start).toISOString(), ende: new Date(ende).toISOString() });
266	        if (slots.length >= TERMIN_GRENZEN.maxSlots) return slots;
267	      }
268	    }
269	  }
270	  return slots;
271	}
