273	/** Liegt ein gewünschter Beginn exakt auf einem freien Slot? (Serverprüfung der Buchung) */
274	export function slotFrei(startIso, param) {
275	  const start = new Date(startIso).getTime();
276	  if (!Number.isFinite(start)) return false;
277	  const tag = wandzeit(start).tag;
278	  return freieSlots({ ...param, vonTag: tag, bisTag: tag }).some((s) => new Date(s.start).getTime() === start);
279	}
