285	/** Text maskieren (Backslash, Semikolon, Komma, Zeilenumbruch) */
286	export const icsText = (t) => String(t ?? "").replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r?\n/g, "\\n");
