288	/** Zeilen auf 75 Oktette falten (UTF-8, ohne Zeichen zu zerteilen) */
289	function falten(zeile) {
290	  const enc = new TextEncoder();
291	  if (enc.encode(zeile).length <= 75) return zeile;
292	  const teile = [];
293	  let aktuell = "";
294	  let bytes = 0;
295	  for (const z of zeile) {
296	    const n = enc.encode(z).length;
297	    const grenze = teile.length ? 74 : 75;
298	    if (bytes + n > grenze) {
299	      teile.push(aktuell);
300	      aktuell = "";
301	      bytes = 0;
302	    }
303	    aktuell += z;
304	    bytes += n;
305	  }
306	  teile.push(aktuell);
307	  return teile.join("\r\n ");
308	}
