321	    t.kanal === "telefon" ? "Wir rufen Sie zum vereinbarten Zeitpunkt an." : t.kanal === "video" ? "Den Link zum Videogespräch erhalten Sie vor dem Termin im Portal." : "",
322	    t.verwaltenLink ? `Umbuchen oder absagen: ${t.verwaltenLink}` : basisUrl ? `Umbuchen oder absagen im Portal: ${basisUrl}/portal/termine` : "",
323	  ].filter(Boolean).join("\n");
324	  const zeilen = [
325	    "BEGIN:VCALENDAR",
326	    "VERSION:2.0",
327	    "PRODID:-//OekoInvest GmbH//Plattform Termine//DE",
328	    "CALSCALE:GREGORIAN",
329	    `METHOD:${methode}`,
330	    "BEGIN:VEVENT",
