339	    organisator?.email ? `ORGANIZER;CN=${icsText(organisator.name || "ÖkoInvest")}:mailto:${organisator.email}` : null,
340	    `STATUS:${storniert ? "CANCELLED" : "CONFIRMED"}`,
341	    "TRANSP:OPAQUE",
342	    storniert ? null : "BEGIN:VALARM",
343	    storniert ? null : "TRIGGER:-PT30M",
344	    storniert ? null : "ACTION:DISPLAY",
345	    storniert ? null : `DESCRIPTION:${icsText(art?.label || "Termin")}`,
346	    storniert ? null : "END:VALARM",
347	    "END:VEVENT",
348	    "END:VCALENDAR",
