 51	function artPruefen(n, art) {
 52	  const a = TERMIN_ARTEN[art];
 53	  if (!a) throw new PlattformFehler(422, "Unbekannte Terminart.");
 54	  if (a.oeffentlich) return a;
 55	  if (!n) throw new PlattformFehler(401, "Bitte melden Sie sich an.");
 56	  if (!n.rollen?.includes("admin") && !(a.rollen || []).some((r) => n.rollen?.includes(r))) throw verboten("Diese Terminart steht Ihrem Konto nicht zur Verfügung.");
