 60	function zeitraum({ von, bis } = {}) {
 61	  const heute = heuteTag();
 62	  const vonTag = tagGueltig(von) && von >= heute ? von : heute;
 63	  const maxBis = tagPlus(heute, TERMIN_GRENZEN.horizontTage);
 64	  let bisTag = tagGueltig(bis) ? bis : tagPlus(vonTag, 13);
 65	  if (bisTag > maxBis) bisTag = maxBis;
 66	  if (bisTag < vonTag) bisTag = vonTag;
 67	  return { vonTag, bisTag };
 68	}
