118	  const text = `${a?.label || "Termin"}: ${zeitraumText(t.start, t.ende)}\nAnsprechperson: ${nameVon(db, t.mitarbeiterId) || "ÖkoInvest"}\n${t.kanal === "telefon" ? "Wir rufen Sie zum vereinbarten Zeitpunkt an." : t.kanal === "video" ? "Den Link zum Videogespräch erhalten Sie vor dem Termin." : t.ort ? `Ort: ${t.ort}` : "Den Treffpunkt stimmen wir mit Ihnen ab."}\n\nDie Kalenderdatei (ICS) ist angehängt.`;
119	  const anhang = { name: "termin.ics", mime: "text/calendar", inhalt: ics };
120	  if (t.kontakt?.email) {
121	    mailAblegen(db, {
122	      an: t.kontakt.email, anName: t.kontakt.name, nutzerId: t.kontoId || null, art: "termin", betreff: `${betreff} – ÖkoInvest`, text,
123	      link: t.kontoId ? "/portal/termine" : t.tokenLink || "/portal", linkText: t.kontoId ? "Termin im Portal" : "Termin verwalten", hinweis: "Umbuchen oder absagen können Sie über den Link – bis zum Beginn des Termins.", anhang,
124	    });
125	  }
126	  const m = nutzerById(db, t.mitarbeiterId);
127	  if (m && anlass !== "erinnerung") mailAblegen(db, { an: m.email, anName: nameVon(db, m.id), nutzerId: m.id, art: "termin", betreff: `${betreff} (${t.kontakt?.name || "Kunde"}) – Kalender`, text, link: "/portal/admin/kalender", linkText: "Zum Kalender", anhang });
