130	/** Mitarbeiter für eine Buchung wählen: Wunsch → Gebietsverantwortlicher → geringste Belegung */
131	function mitarbeiterWaehlen(db, art, start, { wunschId = null, ort = {} } = {}) {
132	  const kandidaten = anbieter(db, art).filter((k) => slotFrei(start, slotParameter(db, k.id, art)));
133	  if (wunschId) return kandidaten.find((k) => k.id === wunschId)?.id || null;
134	  if (!kandidaten.length) return null;
135	  if (["besichtigung", "gemeinde"].includes(art) && ort.land) {
136	    const g = gebietFuer(db.bo?.gebiete || [], ort);
137	    const gid = g?.gebiet?.mitarbeiterId;
138	    if (gid && kandidaten.some((k) => k.id === gid)) return gid;
139	  }
140	  const last = (id) => db.service.termine.filter((t) => t.mitarbeiterId === id && TERMIN_AKTIV.includes(t.status) && new Date(t.start) > new Date()).length;
141	  return [...kandidaten].sort((a, b) => last(a.id) - last(b.id))[0].id;
142	}
