146	export function erinnerungenPruefen(db) {
147	  const grenze = Date.now() + TERMIN_GRENZEN.erinnerungStunden * 3600e3;
148	  let anzahl = 0;
149	  for (const t of db.service.termine) {
150	    if (!TERMIN_AKTIV.includes(t.status) || t.erinnertAm) continue;
151	    const s = new Date(t.start).getTime();
152	    if (s < Date.now() || s > grenze) continue;
153	    t.erinnertAm = jetzt();
154	    icsVersenden(db, t, { anlass: "erinnerung" });
155	    if (t.kontoId) melden(db, t.kontoId, { art: "termin", titel: `Erinnerung: ${TERMIN_ARTEN[t.art]?.label}`, text: zeitraumText(t.start, t.ende), link: "/portal/termine", objektArt: "termin", objektId: t.id }, { mail: false });
156	    anzahl++;
157	  }
158	  return anzahl;
159	}
