163	export async function terminSlots(n, { art, von, bis, mitarbeiterId = "" } = {}) {
164	  const a = artPruefen(n, art);
165	  const db = await lesenBereit();
166	  const { vonTag, bisTag } = zeitraum({ von, bis });
167	  const bo = n && boLesen(n, BEREICH);
168	  let liste = anbieter(db, art);
169	  if (mitarbeiterId && bo) liste = liste.filter((k) => k.id === mitarbeiterId);
170	  const map = new Map();
171	  for (const k of liste) {
172	    for (const s of freieSlots({ ...slotParameter(db, k.id, art), vonTag, bisTag })) {
173	      const e = map.get(s.start) || { start: s.start, ende: s.ende, anzahl: 0, mitarbeiter: [] };
174	      e.anzahl++;
175	      if (bo) e.mitarbeiter.push({ id: k.id, name: nameVon(db, k.id) });
176	      map.set(s.start, e);
177	    }
178	  }
179	  const slots = [...map.values()].sort((x, y) => x.start.localeCompare(y.start)).slice(0, TERMIN_GRENZEN.maxSlots).map((s) => (bo ? s : { start: s.start, ende: s.ende }));
180	  return { art, artLabel: a.label, dauer: a.dauer, kanal: a.kanal, von: vonTag, bis: bisTag, slots };
181	}
