183	function kontaktPruefen(k = {}) {
184	  const name = v.text(k.name || [k.vorname, k.nachname].filter(Boolean).join(" "), 120);
185	  v.pflicht(name.length >= 2, "Bitte geben Sie Ihren Namen an.");
186	  const email = v.email(k.email);
187	  v.pflicht(email, "Bitte geben Sie eine gültige E-Mail-Adresse an.");
188	  return { name, email, telefon: v.text(k.telefon, 40), firma: v.text(k.firma, 120), plz: v.text(k.plz, 10), ort: v.text(k.ort, 80), land: v.auswahl(k.land, ["DE", "AT", "CH"], "") };
189	}
