191	/**
192	 * Termin buchen. n = angemeldetes Konto oder null (öffentlich). Backoffice kann `fuerKontoId` und `mitarbeiterId` setzen.
193	 * Liefert { termin, verwaltenToken? } – das Token nur bei öffentlichen Buchungen (steht auch in der Bestätigungs-Mail).
194	 */
195	export async function terminBuchen(n, daten = {}, { ip = "" } = {}) {
196	  const art = v.auswahl(daten.art, TERMIN_ART_IDS, "");
197	  const a = artPruefen(n, art);
198	  const start = new Date(daten.start || "");
199	  v.pflicht(!Number.isNaN(start.getTime()), "Bitte wählen Sie einen Termin.");
200	  const bo = n && boSchreiben(n, BEREICH);
201	  if (!n) v.pflicht(v.wahr(daten.einwilligung), "Bitte stimmen Sie der Verarbeitung Ihrer Angaben zur Terminvereinbarung zu.");
202	  const kanal = a.kanal === "vor_ort" || !daten.kanal ? a.kanal : v.auswahl(daten.kanal, ["telefon", "video"], a.kanal);
203	  const notiz = v.mehrzeilig(daten.notiz, 1000);
204	  return aendernBereit((db) => {
205	    let kontoId = null;
206	    let kontakt;
207	    if (n && !bo) {
208	      const u = nutzerById(db, n.id);
209	      kontoId = u.id;
210	      kontakt = { name: nameVon(db, u.id), email: u.email, telefon: v.text(daten.telefon, 40) || u.telefon || "", firma: u.firma || "", plz: v.text(daten.kontakt?.plz, 10), ort: v.text(daten.kontakt?.ort, 80), land: v.auswahl(daten.kontakt?.land, ["DE", "AT", "CH"], "") };
211	    } else if (bo && daten.fuerKontoId) {
212	      const u = nutzerById(db, v.kennung(daten.fuerKontoId));
213	      if (!u) throw nichtGefunden("Konto nicht gefunden.");
214	      kontoId = u.id;
215	      kontakt = { name: nameVon(db, u.id), email: u.email, telefon: u.telefon || "", firma: u.firma || "" };
216	    } else kontakt = kontaktPruefen(daten.kontakt);
217	    // Missbrauchsschutz: höchstens 3 künftige aktive Termine je E-Mail-Adresse
218	    const offen = db.service.termine.filter((t) => t.kontakt?.email === kontakt.email && TERMIN_AKTIV.includes(t.status) && new Date(t.start) > new Date());
219	    if (!bo && offen.length >= 3) throw konflikt("Sie haben bereits drei offene Termine. Bitte sagen Sie einen ab oder melden Sie sich über das Portal.");
220	    const iso = start.toISOString();
221	    const mitarbeiterId = mitarbeiterWaehlen(db, art, iso, { wunschId: bo ? v.kennung(daten.mitarbeiterId) || null : null, ort: { land: kontakt.land, bundesland: v.text(daten.kontakt?.bundesland, 60), plz: kontakt.plz } });
222	    if (!mitarbeiterId) throw konflikt("Dieser Zeitpunkt ist nicht (mehr) frei. Bitte wählen Sie einen anderen Termin.");
223	    const t = {
224	      id: neueId("TE"), art, start: iso, ende: new Date(start.getTime() + a.dauer * 60e3).toISOString(), mitarbeiterId, vertretungFuerId: null, kontoId, kontakt,
225	      kanal, ort: a.kanal === "vor_ort" ? v.text(daten.ort || [kontakt.plz, kontakt.ort].filter(Boolean).join(" "), 160) : "", notiz,
226	      bezugArt: v.auswahl(daten.bezugArt, ["vorgang", "flaeche", "projekt"], "") || null, bezugId: v.kennung(daten.bezugId) || null,
227	      status: "gebucht", sequenz: 0, erinnertAm: null, herkunft: bo ? "backoffice" : n ? "portal" : v.auswahl(daten.herkunft, ["kontakt", "flaechencheck", "website"], "website"),
228	      tokenHash: null, verlauf: [], erstelltAm: jetzt(), ip: ip || "",
229	    };
230	    let token = null;
231	    if (!kontoId) {
232	      token = zufallsToken();
233	      t.tokenHash = sha256(token);
234	      t.token = token; // nur für den Versand in dieser Transaktion, wird unten entfernt
235	      t.tokenLink = `/termin/verwalten?token=${token}`;
236	    }
237	    verlauf(t, `Gebucht (${t.herkunft}) – zuständig ${nameVon(db, mitarbeiterId)}`, n);
238	    db.service.termine.push(t);
239	    icsVersenden(db, t, { anlass: "neu" });
240	    delete t.token;
241	    delete t.tokenLink;
242	    melden(db, mitarbeiterId, { art: "termin", titel: `Neuer Termin: ${a.label}`, text: `${zeitraumText(t.start, t.ende)} · ${kontakt.name}`, link: "/portal/admin/kalender", objektArt: "termin", objektId: t.id }, { mail: false });
243	    if (kontoId) melden(db, kontoId, { art: "termin", titel: `Termin gebucht: ${a.label}`, text: zeitraumText(t.start, t.ende), link: "/portal/termine", objektArt: "termin", objektId: t.id }, { mail: false });
244	    protokoll(db, n, "termin", "termin", t.id, `Termin ${a.label} gebucht (${zeitraumText(t.start, t.ende)})`, ip);
245	    return { termin: ausgabe(db, n || null, t), verwaltenToken: token };
246	  });
247	}
