251	export async function termine(n, { alle = false, von = "", bis = "", mitarbeiterId = "", status = "" } = {}) {
252	  angemeldet(n);
253	  const bo = boLesen(n, BEREICH);
254	  if (alle && bo) {
255	    // Erinnerungen fällig? (Demo-Ersatz für den stündlichen Frappe-Job)
256	    await aendernBereit((db) => erinnerungenPruefen(db));
257	  }
258	  const db = await lesenBereit();
259	  const vonMs = tagGueltig(von) ? new Date(`${von}T00:00:00Z`).getTime() - 86400e3 : -Infinity;
260	  const bisMs = tagGueltig(bis) ? new Date(`${bis}T23:59:59Z`).getTime() + 86400e3 : Infinity;
261	  return db.service.termine
262	    .filter((t) => (alle && bo ? true : t.kontoId === n.id || t.mitarbeiterId === n.id))
263	    .filter((t) => !mitarbeiterId || t.mitarbeiterId === mitarbeiterId)
264	    .filter((t) => !status || t.status === status)
265	    .filter((t) => {
266	      const s = new Date(t.start).getTime();
267	      return s >= vonMs && s <= bisMs;
268	    })
269	    .sort((a, b) => a.start.localeCompare(b.start))
270	    .slice(0, 1000)
271	    .map((t) => ausgabe(db, n, t));
272	}
