286	
287	function aktionAnwenden(db, n, t, { aktion, start, grund = "", mitarbeiterId }, { alsKunde }) {
288	  const a = TERMIN_ARTEN[t.art];
289	  const kommend = new Date(t.start).getTime() > Date.now();
290	  if (aktion === "stornieren") {
291	    if (!TERMIN_AKTIV.includes(t.status)) throw konflikt("Der Termin ist nicht mehr aktiv.");
292	    if (alsKunde && !kommend) throw konflikt("Vergangene Termine können nicht abgesagt werden.");
293	    t.status = "storniert";
294	    t.sequenz = (t.sequenz || 0) + 1;
295	    verlauf(t, `Abgesagt${grund ? `: ${v.text(grund, 200)}` : ""}`, n);
296	    icsVersenden(db, t, { anlass: "storniert" });
297	    melden(db, alsKunde ? t.mitarbeiterId : t.kontoId, { art: "termin", titel: `Termin abgesagt: ${a.label}`, text: zeitraumText(t.start, t.ende), link: alsKunde ? "/portal/admin/kalender" : "/portal/termine", objektArt: "termin", objektId: t.id }, { mail: false });
298	    return;
299	  }
300	  if (aktion === "umbuchen") {
301	    if (!TERMIN_AKTIV.includes(t.status) || !kommend) throw konflikt("Nur künftige, aktive Termine können verschoben werden.");
302	    const neu = new Date(start || "");
303	    v.pflicht(!Number.isNaN(neu.getTime()), "Bitte wählen Sie einen neuen Termin.");
304	    const iso = neu.toISOString();
305	    // gleiche Person bevorzugt, sonst eine andere mit freiem Slot
306	    let ziel = slotFrei(iso, slotParameter(db, t.mitarbeiterId, t.art, { ohneId: t.id })) ? t.mitarbeiterId : null;
307	    if (!ziel) ziel = mitarbeiterWaehlen(db, t.art, iso);
308	    if (!ziel) throw konflikt("Dieser Zeitpunkt ist nicht (mehr) frei. Bitte wählen Sie einen anderen Termin.");
309	    const alt = zeitraumText(t.start, t.ende);
310	    t.start = iso;
311	    t.ende = new Date(neu.getTime() + a.dauer * 60e3).toISOString();
312	    t.mitarbeiterId = ziel;
313	    t.status = "gebucht";
314	    t.erinnertAm = null;
315	    t.sequenz = (t.sequenz || 0) + 1;
316	    verlauf(t, `Verschoben von ${alt} auf ${zeitraumText(t.start, t.ende)}`, n);
317	    icsVersenden(db, t, { anlass: "umgebucht" });
318	    melden(db, alsKunde ? t.mitarbeiterId : t.kontoId, { art: "termin", titel: `Termin verschoben: ${a.label}`, text: zeitraumText(t.start, t.ende), link: alsKunde ? "/portal/admin/kalender" : "/portal/termine", objektArt: "termin", objektId: t.id }, { mail: false });
319	    return;
320	  }
321	  if (alsKunde) throw verboten("Diese Änderung kann nur das Backoffice vornehmen.");
322	  if (aktion === "bestaetigen") {
323	    if (t.status !== "gebucht") throw konflikt("Nur gebuchte Termine können bestätigt werden.");
324	    t.status = "bestaetigt";
325	    verlauf(t, "Bestätigt", n);
326	    icsVersenden(db, t, { anlass: "bestaetigt" });
327	    return;
328	  }
329	  if (aktion === "erledigt" || aktion === "nicht_erschienen") {
330	    if (!TERMIN_AKTIV.includes(t.status)) throw konflikt("Der Termin ist nicht mehr aktiv.");
331	    t.status = aktion;
332	    verlauf(t, TERMIN_STATUS[aktion].label, n);
333	    return;
334	  }
335	  if (aktion === "zuweisen") {
336	    const z = nutzerById(db, v.kennung(mitarbeiterId));
337	    v.pflicht(z && z.aktiv && z.rollen.includes("admin"), "Zuständig kann nur ein aktives Backoffice-Konto sein.");
