430	/** Für HR: aktive Termine eines Mitarbeiters im Zeitraum an die Vertretung übergeben (innerhalb von aendern) */
431	export function termineVertreten(db, n, abw) {
432	  let anzahl = 0;
433	  for (const t of db.service.termine) {
434	    if (t.mitarbeiterId !== abw.mitarbeiterId || !TERMIN_AKTIV.includes(t.status)) continue;
435	    const tag = new Date(t.start).toLocaleDateString("sv-SE", { timeZone: "Europe/Vienna" });
436	    if (tag < abw.von || tag > abw.bis) continue;
437	    const ziel = vertretungFinden({ mitarbeiterId: abw.mitarbeiterId, tag, abwesenheiten: db.service.abwesenheiten, mitarbeiter: db.service.mitarbeiter });
438	    if (!ziel || ziel.id === abw.mitarbeiterId) continue;
439	    // Keine Doppelbuchung bei der Vertretung: belegt → Termin bleibt, Hinweis im Verlauf (Backoffice klärt manuell)
440	    const s = new Date(t.start).getTime();
441	    const e = new Date(t.ende).getTime();
442	    if (belegtVon(db, ziel.id, t.id).some((b) => new Date(b.start).getTime() < e && s < new Date(b.ende).getTime())) {
443	      verlauf(t, `Vertretung ${nameVon(db, ziel.id)} ist zu dieser Zeit belegt – bitte manuell zuweisen`, n);
444	      continue;
445	    }
446	    t.vertretungFuerId = t.vertretungFuerId || abw.mitarbeiterId;
447	    t.mitarbeiterId = ziel.id;
448	    t.sequenz = (t.sequenz || 0) + 1;
449	    verlauf(t, `Vertretung wegen Abwesenheit: ${nameVon(db, abw.mitarbeiterId)} → ${nameVon(db, ziel.id)}`, n);
450	    icsVersenden(db, t, { anlass: "vertretung" });
451	    anzahl++;
452	  }
453	  return anzahl;
454	}

