 33	function mitarbeiterZeile(db, n, u) {
 34	  const m = db.service.mitarbeiter[u.id] || {};
 35	  const heute = heuteTag();
 36	  const in7 = tagPlus(heute, 7);
 37	  const ab = db.service.abwesenheiten.filter((a) => a.mitarbeiterId === u.id && a.status !== "abgelehnt" && a.bis >= heute).sort((a, b) => a.von.localeCompare(b.von));
 38	  const termineWoche = db.service.termine.filter((t) => t.mitarbeiterId === u.id && TERMIN_AKTIV.includes(t.status) && t.start.slice(0, 10) >= heute && t.start.slice(0, 10) <= in7);
 39	  const aufgabenOffen = (db.aufgaben || []).filter((a) => a.zustaendigId === u.id && a.status === "offen").length;
 40	  const ticketsOffen = db.service.tickets.filter((t) => t.zustaendigId === u.id && TICKET_OFFEN.includes(t.status)).length;
 41	  const signaturenOffen = db.service.signaturen.filter((s) => s.erstellerId === u.id && s.status === "laufend").length;
 42	  const abwesendeTage = ab.reduce((s, a) => {
 43	    const von = a.von > heute ? a.von : heute;
 44	    const bis = a.bis < in7 ? a.bis : in7;
 45	    return s + (bis >= von ? Math.min(5, tageZwischen(von, bis)) : 0);
 46	  }, 0);
 47	  const monat = heute.slice(0, 7);
 48	  const stundenMonat = db.service.zeiten.filter((z) => z.kontoId === u.id && z.datum.startsWith(monat)).reduce((s, z) => s + z.stunden, 0);
 49	  return {
 50	    id: u.id, name: nameVon(db, u.id), email: u.email, backofficeRollen: u.backofficeRollen || ["leitung"], funktion: m.funktion || "", employeeId: m.employeeId || "",
 51	    vertretung: kontoKurz(db, m.vertretungId), kapazitaetStunden: m.kapazitaetStunden ?? 38.5, aktiv: m.aktiv !== false,
 52	    gebiete: (db.bo?.gebiete || []).filter((g) => g.mitarbeiterId === u.id && g.aktiv !== false).map((g) => ({ id: g.id, name: g.name })),
 53	    abwesendHeute: abwesenheitAm(db.service.abwesenheiten, u.id, heute) ? true : false,
 54	    abwesenheiten: ab.slice(0, 5).map((a) => ({ id: a.id, von: a.von, bis: a.bis, art: a.art, artLabel: ABWESENHEIT_ARTEN[a.art], vertretung: kontoKurz(db, a.vertretungId) })),
 55	    last: { termine: termineWoche.length, terminMinuten: termineWoche.reduce((s, t) => s + (new Date(t.ende) - new Date(t.start)) / 60e3, 0), aufgabenOffen, ticketsOffen, signaturenOffen },
 56	    auslastung: auslastung({ kapazitaetStunden: m.kapazitaetStunden ?? 38.5, terminMinuten: termineWoche.reduce((s, t) => s + (new Date(t.ende) - new Date(t.start)) / 60e3, 0), aufgabenOffen, ticketsOffen, signaturenOffen, abwesendeTage }),
 57	    stundenMonat: Math.round(stundenMonat * 100) / 100,
 58	    ich: u.id === n.id,
 59	  };
 60	}
