112	/** Offene Aufgaben, Termine und Tickets im Zeitraum an die Vertretung übergeben (innerhalb von aendern) */
113	function vertretungAnwenden(db, n, abw) {
114	  const ergebnis = { aufgaben: 0, termine: 0, tickets: 0, hinweis: false };
115	  const ziel = (tag) => vertretungFinden({ mitarbeiterId: abw.mitarbeiterId, tag, abwesenheiten: db.service.abwesenheiten, mitarbeiter: db.service.mitarbeiter });
116	  for (const a of db.aufgaben || []) {
117	    if (a.zustaendigId !== abw.mitarbeiterId || a.status !== "offen" || !a.faelligAm) continue;
118	    if (a.faelligAm < abw.von || a.faelligAm > abw.bis) continue;
119	    const z = ziel(a.faelligAm);
120	    if (!z || z.id === abw.mitarbeiterId) continue;
121	    a.vertretungFuerId = abw.mitarbeiterId;
122	    a.zustaendigId = z.id;
123	    ergebnis.aufgaben++;
124	    melden(db, z.id, { art: "aufgabe", titel: `Vertretung: ${a.titel}`, text: `für ${nameVon(db, abw.mitarbeiterId)} (abwesend bis ${abw.bis.split("-").reverse().join(".")})`, link: "/portal/admin/aufgaben?ansicht=meine", objektArt: a.bezugArt || "aufgabe", objektId: a.bezugId || a.id });
125	  }
126	  ergebnis.termine = termineVertreten(db, n, abw);
127	  const heute = heuteTag();
128	  if (abw.von <= heute && heute <= abw.bis) {
129	    for (const t of db.service.tickets) {
130	      if (t.zustaendigId !== abw.mitarbeiterId || !TICKET_OFFEN.includes(t.status)) continue;
131	      const z = ziel(heute);
132	      if (!z || z.id === abw.mitarbeiterId) continue;
133	      t.zustaendigId = z.id;
134	      t.verlauf.push({ am: jetzt(), text: `Vertretung wegen Abwesenheit von ${nameVon(db, abw.mitarbeiterId)}`, vonId: n.id });
135	      ergebnis.tickets++;
136	    }
137	  }
138	  // Zuweisungen (Vorgänge/Flächen) bleiben beim Verantwortlichen – die Vertretung bekommt eine Hinweis-Aufgabe
139	  const zuweisungen = [...(db.vorgaenge || []), ...(db.flaechen || [])].filter((o) => o.zustaendigId === abw.mitarbeiterId && !["abgeschlossen", "abgelehnt", "zurueckgezogen", "vertrag"].includes(o.status)).length;
140	  const zv = ziel(abw.von);
141	  if (zuweisungen && zv && zv.id !== abw.mitarbeiterId) {
142	    db.aufgaben = db.aufgaben || [];
143	    db.aufgaben.push({ id: neueId("AF"), titel: `Vertretung ${nameVon(db, abw.mitarbeiterId)}: ${zuweisungen} offene Zuweisungen im Blick behalten`, beschreibung: `Abwesenheit ${abw.von.split("-").reverse().join(".")}–${abw.bis.split("-").reverse().join(".")}. Neue Nachrichten zu diesen Vorgängen und Flächen bitte vertretungsweise beantworten.`, faelligAm: abw.von, zustaendigId: zv.id, bezugArt: null, bezugId: null, status: "offen", erstelltVon: n.id, erstelltAm: jetzt(), erledigtAm: null, erledigtVon: null, erinnertAm: null, vertretungFuerId: abw.mitarbeiterId });
144	    ergebnis.hinweis = true;
145	  }
146	  return ergebnis;
147	}
