151	  const von = String(daten.von || "");
152	  const bis = String(daten.bis || daten.von || "");
153	  v.pflicht(tagGueltig(von) && tagGueltig(bis) && bis >= von, "Bitte geben Sie einen gültigen Zeitraum an (von ≤ bis).");
154	  v.pflicht(tageZwischen(von, bis) <= HR_GRENZEN.abwesenheitTageMax, `Höchstens ${HR_GRENZEN.abwesenheitTageMax} Tage je Eintrag.`);
155	  const art = v.auswahl(daten.art, ABWESENHEIT_ART_IDS, "urlaub");
156	  return aendernBereit((db) => {
157	    const kontoId = v.kennung(daten.mitarbeiterId) || n.id;
158	    if (kontoId !== n.id && !boSchreiben(n, "team")) throw verboten("Abwesenheiten anderer erfasst nur die Leitung.");
159	    const u = nutzerById(db, kontoId);
160	    v.pflicht(u && u.rollen.includes("admin"), "Nur für Backoffice-Konten.");
161	    const ueberschneidung = db.service.abwesenheiten.find((a) => a.mitarbeiterId === kontoId && a.status !== "abgelehnt" && a.von <= bis && von <= a.bis);
162	    if (ueberschneidung) throw konflikt("Für diesen Zeitraum ist bereits eine Abwesenheit eingetragen.");
163	    const vz = daten.vertretungId ? nutzerById(db, v.kennung(daten.vertretungId)) : null;
164	    if (daten.vertretungId) v.pflicht(vz && vz.aktiv && vz.rollen.includes("admin") && vz.id !== kontoId, "Vertretung muss ein anderes, aktives Backoffice-Konto sein.");
165	    const abw = { id: neueId("AB"), mitarbeiterId: kontoId, von, bis, art, vertretungId: vz?.id || db.service.mitarbeiter[kontoId]?.vertretungId || null, status: "genehmigt", quelle: "plattform", bemerkung: v.text(daten.bemerkung, 200), erstelltAm: jetzt(), erstelltVon: n.id };
166	    db.service.abwesenheiten.push(abw);
167	    const ergebnis = vertretungAnwenden(db, n, abw);
168	    protokoll(db, n, "team", "nutzer", kontoId, `Abwesenheit ${von}–${bis} (${ABWESENHEIT_ARTEN[art]}) – Vertretung: ${ergebnis.aufgaben} Aufgaben, ${ergebnis.termine} Termine, ${ergebnis.tickets} Tickets`);
169	    return { abwesenheit: { ...abw, mitarbeiter: kontoKurz(db, kontoId), vertretung: kontoKurz(db, abw.vertretungId), artLabel: ABWESENHEIT_ARTEN[art] }, vertretung: ergebnis };
170	  });
