 95	// ---------------------------------------------------------------- Webhook-Signatur
 96	
 97	function hmac(alg, geheimnis, daten, kodierung) {
 98	  return createHmac(alg, geheimnis).update(daten).digest(kodierung);
 99	}
100	
101	/** Zeitkonstanter Vergleich zweier Signaturen (unterschiedliche Längen → false) */
102	export function signaturGleich(a, b) {
103	  const x = Buffer.from(String(a || ""), "utf8");
104	  const y = Buffer.from(String(b || ""), "utf8");
105	  if (!x.length || x.length !== y.length) return false;
106	  return timingSafeEqual(x, y);
107	}
108	
109	const ALG_AUS_HEADER = { HMAC_SHA1_HEX: "sha1", HMAC_SHA256_HEX: "sha256", HMAC_SHA512_HEX: "sha512" };
110	
111	/**
112	 * Signatur eines eingehenden Webhooks prüfen.
113	 * kopf: Funktion (name) => Wert (z. B. request.headers.get), roh: Roh-Body als String (NICHT neu serialisieren).
114	 * Liefert { ok, grund }. Bei „zeit.body“ zusätzlich Zeitfenster ±5 min (Wiederholungsschutz).
115	 */
116	export function webhookSignaturPruefen(anbieter, kopf, roh, { geheimnis, jetztMs = Date.now() } = {}) {
117	  const def = IDENT_ANBIETER[anbieter]?.signatur;
118	  if (!def) return { ok: false, grund: "anbieter" };
119	  if (!geheimnis) return { ok: false, grund: "kein_geheimnis" };
120	  let gesendet = String(kopf(def.header) || "").trim();
121	  if (!gesendet) return { ok: false, grund: "keine_signatur" };
122	  if (gesendet.startsWith("sha256=")) gesendet = gesendet.slice(7);
123	  let alg = def.alg;
124	  if (def.algHeader) {
125	    const a = ALG_AUS_HEADER[String(kopf(def.algHeader) || "").toUpperCase()];
126	    if (a) alg = a;
127	    if (alg === "sha1") return { ok: false, grund: "algorithmus" }; // SHA-1 nicht akzeptieren
128	  }
129	  let daten = roh;
130	  if (def.ueber === "zeit.body") {
131	    const zeit = Number(kopf(def.zeitHeader));
132	    if (!Number.isFinite(zeit) || Math.abs(jetztMs - zeit * 1000) > 5 * 60 * 1000) return { ok: false, grund: "zeit" };
133	    daten = `${zeit}.${roh}`;
134	  }
135	  const erwartet = hmac(alg, geheimnis, daten, def.kodierung);
136	  return signaturGleich(def.kodierung === "hex" ? gesendet.toLowerCase() : gesendet, erwartet) ? { ok: true, grund: "" } : { ok: false, grund: "signatur" };
137	}
