139	/** Kopfzeilen für einen signierten Webhook erzeugen (Demo-Simulator und Tests) */
140	export function webhookSignieren(anbieter, roh, { geheimnis, zeit = Math.floor(Date.now() / 1000) } = {}) {
141	  const def = IDENT_ANBIETER[anbieter].signatur;
142	  const daten = def.ueber === "zeit.body" ? `${zeit}.${roh}` : roh;
143	  const kopf = { [def.header]: hmac(def.alg, geheimnis, daten, def.kodierung) };
144	  if (def.zeitHeader) kopf[def.zeitHeader] = String(zeit);
145	  if (def.algHeader) kopf[def.algHeader] = "HMAC_SHA256_HEX";
146	  return kopf;
147	}
