158	export function webhookNormalisieren(anbieter, p = {}) {
159	  if (!p || typeof p !== "object") return null;
160	  if (anbieter === "demo") {
161	    const e = ["bestanden", "pruefen", "abgelehnt", "abgebrochen"].includes(p.ergebnis) ? p.ergebnis : null;
162	    if (!e) return null;
163	    return { sitzungId: kurz(p.sitzungId, 40), externeId: kurz(p.externeId, 80), ergebnis: e, verfahren: kurz(p.verfahren, 60) || "Simulation", grund: kurz(p.grund, 300), ereignisId: kurz(p.ereignisId, 80), daten: { nfc: !!p.nfc, liveness: !!p.liveness } };
164	  }
165	  if (anbieter === "veriff") {
166	    const v = p.verification || {};
167	    const status = String(v.status || p.status || "").toLowerCase();
168	    const map = { approved: "bestanden", declined: "abgelehnt", resubmission_requested: "pruefen", review: "pruefen", expired: "abgebrochen", abandoned: "abgebrochen" };
169	    if (!map[status]) return null;
170	    return { sitzungId: kurz(v.vendorData || p.vendorData, 40), externeId: kurz(v.id || p.id, 80), ergebnis: map[status], verfahren: "Veriff", grund: kurz(v.reason || "", 300), ereignisId: kurz(`${v.id || p.id}:${status}`, 80), daten: { code: v.code || null } };
171	  }
172	  if (anbieter === "sumsub") {
173	    if (!["applicantReviewed", "applicantOnHold"].includes(p.type)) return null;
174	    const antwort = p.reviewResult?.reviewAnswer;
175	    const endgueltig = p.reviewResult?.reviewRejectType === "FINAL";
176	    const e = p.type === "applicantOnHold" ? "pruefen" : antwort === "GREEN" ? "bestanden" : antwort === "RED" ? (endgueltig ? "abgelehnt" : "pruefen") : null;
177	    if (!e) return null;
178	    return { sitzungId: kurz(p.externalUserId, 40), externeId: kurz(p.applicantId, 80), ergebnis: e, verfahren: "Sumsub", grund: kurz((p.reviewResult?.rejectLabels || []).join(", "), 300), ereignisId: kurz(`${p.applicantId}:${p.correlationId || p.createdAtMs || p.type}`, 80), daten: {} };
179	  }
180	  if (anbieter === "onfido") {
181	    const r = p.payload || {};
182	    if (r.resource_type !== "workflow_run" || r.action !== "workflow_run.completed") return null;
183	    const status = String(r.object?.status || "").toLowerCase();
184	    const map = { approved: "bestanden", declined: "abgelehnt", review: "pruefen", abandoned: "abgebrochen", error: "pruefen" };
185	    if (!map[status]) return null;
186	    return { sitzungId: kurz(r.object?.tags?.find?.((t) => /^IP-/.test(t)) || r.object?.customer_user_id, 40), externeId: kurz(r.object?.id, 80), ergebnis: map[status], verfahren: "Onfido", grund: "", ereignisId: kurz(`${r.object?.id}:${status}`, 80), daten: {} };
187	  }
188	  if (anbieter === "idnow") {
189	    const ip = p.identificationprocess || {};
190	    const res = String(ip.result || "").toUpperCase();
191	    const map = { SUCCESS: "bestanden", SUCCESS_DATA_CHANGED: "pruefen", REVIEW_PENDING: "pruefen", FRAUD_SUSPICION_PENDING: "pruefen", FRAUD_SUSPICION_CONFIRMED: "abgelehnt", CANCELED: "abgebrochen", ABORTED: "abgebrochen" };
192	    if (!map[res]) return null;
193	    return { sitzungId: kurz(ip.transactionnumber, 40), externeId: kurz(ip.id, 80), ergebnis: map[res], verfahren: `IDnow ${kurz(ip.type || "", 30)}`.trim(), grund: kurz(ip.reason, 300), ereignisId: kurz(`${ip.id}:${res}`, 80), daten: {} };
194	  }
195	  if (anbieter === "webid") {
196	    const res = String(p.result || p.status || "").toLowerCase();
197	    const map = { success: "bestanden", successful: "bestanden", review: "pruefen", failed: "abgelehnt", cancelled: "abgebrochen", canceled: "abgebrochen" };
198	    if (!map[res]) return null;
199	    return { sitzungId: kurz(p.transactionId || p.reference, 40), externeId: kurz(p.actionId || p.id, 80), ergebnis: map[res], verfahren: "WebID", grund: kurz(p.reason, 300), ereignisId: kurz(`${p.actionId || p.id}:${res}`, 80), daten: {} };
200	  }
201	  return null;
202	}
