206	async function abrufen(url, init, { timeoutMs = 15000 } = {}) {
207	  let res;
208	  try {
209	    res = await fetch(url, { ...init, signal: AbortSignal.timeout(timeoutMs), cache: "no-store" });
210	  } catch {
211	    throw Object.assign(new Error("Der Identitätsanbieter ist nicht erreichbar."), { status: 502 });
212	  }
213	  const json = await res.json().catch(() => ({}));
214	  if (!res.ok) throw Object.assign(new Error(`Der Identitätsanbieter hat die Sitzung abgelehnt (HTTP ${res.status}).`), { status: 502 });
215	  return json;
216	}
