218	/**
219	 * Sitzung beim Anbieter anlegen. sitzung: { id (unsere Kennung), vorname, nachname, email, sprache, rueckUrl, webhookUrl }
220	 * Liefert { url, externeId, modus: redirect|embed }. Demo: URL auf die eigene Simulator-Seite.
221	 */
222	export async function sitzungStarten(k, sitzung) {
223	  if (k.anbieter === "demo") {
224	    return { url: `/portal/verifizierung/identitaet?sitzung=${encodeURIComponent(sitzung.id)}`, externeId: `DEMO-${sitzung.id}`, modus: "redirect" };
225	  }
226	  if (!k.aktiv || !k.apiUrl) throw Object.assign(new Error("Die Identitätsprüfung ist nicht konfiguriert."), { status: 503 });
227	  if (k.anbieter === "veriff") {
228	    const j = await abrufen(`${k.apiUrl}/v1/sessions`, {
229	      method: "POST",
230	      headers: { "Content-Type": "application/json", "X-AUTH-CLIENT": k.apiKey },
231	      body: JSON.stringify({ verification: { callback: sitzung.rueckUrl, vendorData: sitzung.id, person: { firstName: sitzung.vorname, lastName: sitzung.nachname } } }),
232	    });
233	    return { url: j.verification?.url, externeId: j.verification?.id, modus: "redirect" };
234	  }
235	  if (k.anbieter === "sumsub") {
236	    const pfad = `/resources/sdkIntegrations/levels/-/websdkLink?ttlInSecs=1800&externalUserId=${encodeURIComponent(sitzung.id)}&levelName=${encodeURIComponent(k.stufe || "basic-kyc-level")}&lang=de`;
237	    const ts = Math.floor(Date.now() / 1000);
238	    const sig = createHmac("sha256", k.apiSecret).update(`${ts}POST${pfad}`).digest("hex");
239	    const j = await abrufen(`${k.apiUrl}${pfad}`, { method: "POST", headers: { "X-App-Token": k.apiKey, "X-App-Access-Ts": String(ts), "X-App-Access-Sig": sig, Accept: "application/json" } });
240	    return { url: j.url, externeId: null, modus: "redirect" };
241	  }
242	  if (k.anbieter === "onfido") {
243	    const kopf = { "Content-Type": "application/json", Authorization: `Token token=${k.apiKey}` };
244	    const a = await abrufen(`${k.apiUrl}/v3.6/applicants`, { method: "POST", headers: kopf, body: JSON.stringify({ first_name: sitzung.vorname, last_name: sitzung.nachname }) });
245	    const w = await abrufen(`${k.apiUrl}/v3.6/workflow_runs`, { method: "POST", headers: kopf, body: JSON.stringify({ workflow_id: k.stufe, applicant_id: a.id, tags: [sitzung.id], link: { completed_redirect_url: sitzung.rueckUrl } }) });
246	    return { url: w.link?.url, externeId: w.id, modus: "redirect" };
247	  }
248	  // IDnow / WebID: Start-Aufrufe sind produkt- und vertragsspezifisch (Firmenkennung, Produkt, Login-Token) –
249	  // Anbindung nach Vertragsschluss gemäß Anbieter-Handbuch ergänzen.
250	  throw Object.assign(new Error(`Die Anbindung an ${IDENT_ANBIETER[k.anbieter]?.label || k.anbieter} ist vorbereitet, aber noch nicht freigeschaltet.`), { status: 501 });
251	}

  1	// src/lib/plattform/dienste/identitaet/mrz.js
  2	//
  3	// Automatische VORPRÜFUNG von Ausweisdokumenten über die maschinenlesbare Zone (MRZ) nach ICAO Doc 9303
  4	// (Teil 3: Prüfziffern, Teil 4: TD3 = Reisepass, Teil 5: TD1 = Personalausweis im Kartenformat, Teil 6: TD2).
  5	// Client- und serverseitig nutzbar (keine Node-Importe) – das Portal prüft sofort beim Eintippen, der Server
  6	// prüft erneut und hängt das Ergebnis als Hinweis an den KYC-Fall.
  7	//
  8	// WICHTIG: „automatisch plausibel“ ersetzt KEINE Identifizierung nach GwG. Prüfziffern belegen nur, dass die
  9	// abgetippte Zeile in sich stimmig ist – nicht, dass das Dokument echt ist oder der Person gehört. Die Entscheidung
 10	// trifft der zugelassene Identitätsanbieter bzw. die Compliance (manuelle Prüfung).
 11	//
 12	// Frappe-Gegenstück: Backend-Import/oekoinvest_app/oekoinvest_app/plattform/dienste_kern.py (gleiche Regeln).
 13	
 14	/** Zeichenwert nach ICAO 9303 Teil 3: 0–9 → 0–9, A–Z → 10–35, „<“ → 0 */
 15	function zeichenWert(c) {
 16	  if (c >= "0" && c <= "9") return c.charCodeAt(0) - 48;
 17	  if (c >= "A" && c <= "Z") return c.charCodeAt(0) - 55;
 18	  if (c === "<") return 0;
 19	  return -1;
 20	}
 21	
 22	/** Prüfziffer (Gewichte 7-3-1, Summe mod 10). Liefert Zahl 0–9 oder null bei ungültigen Zeichen. */
 23	export function pruefziffer(feld) {
 24	  const gewichte = [7, 3, 1];
 25	  let summe = 0;
 26	  const s = String(feld || "");
 27	  for (let i = 0; i < s.length; i++) {
 28	    const w = zeichenWert(s[i]);
 29	    if (w < 0) return null;
 30	    summe += w * gewichte[i % 3];
 31	  }
 32	  return summe % 10;
 33	}
 34	
 35	/** Stimmt die Prüfziffer? `ziffer` ist das Zeichen aus der MRZ („<“ gilt als 0, z. B. bei leeren optionalen Feldern). */
 36	export function pruefzifferOk(feld, ziffer) {
 37	  const soll = pruefziffer(feld);
 38	  if (soll === null) return false;
 39	  const ist = ziffer === "<" ? 0 : Number(ziffer);
 40	  return Number.isInteger(ist) && ist === soll;
 41	}
 42	
 43	/** Eingabe vereinheitlichen: Großbuchstaben, typische OCR-/Tippfehler an Füllzeichen, Zeilen trennen */
 44	export function mrzNormalisieren(eingabe) {
 45	  const zeilen = String(eingabe || "")
 46	    .toUpperCase()
 47	    .replace(/[«‹]/g, "<")
 48	    .replace(/\r/g, "")
 49	    .split("\n")
 50	    .map((z) => z.replace(/\s+/g, "").replace(/[^A-Z0-9<]/g, ""))
 51	    .filter(Boolean);
 52	  // Einzeilige Eingabe (alles hintereinander) nach Länge aufteilen
 53	  if (zeilen.length === 1) {
 54	    const z = zeilen[0];
 55	    if (z.length === 90) return [z.slice(0, 30), z.slice(30, 60), z.slice(60)];
 56	    if (z.length === 88) return [z.slice(0, 44), z.slice(44)];
 57	    if (z.length === 72) return [z.slice(0, 36), z.slice(36)];
 58	  }
 59	  return zeilen;
 60	}
 61	
 62	/** Format erkennen: TD1 (3×30), TD2 (2×36), TD3 (2×44) */
 63	export function mrzFormat(zeilen) {
 64	  if (zeilen.length === 3 && zeilen.every((z) => z.length === 30)) return "TD1";
 65	  if (zeilen.length === 2 && zeilen.every((z) => z.length === 44)) return "TD3";
 66	  if (zeilen.length === 2 && zeilen.every((z) => z.length === 36)) return "TD2";
 67	  return null;
 68	}
 69	
 70	const fueller = (s) => String(s || "").replace(/</g, " ").replace(/\s+/g, " ").trim();
 71	
 72	/** Name aus dem Namensfeld: PRIMÄR<<SEKUNDÄR (Nachname<<Vornamen) */
 73	function nameTeilen(feld) {
 74	  const [nach, ...rest] = String(feld || "").split("<<");
 75	  return { nachname: fueller(nach), vornamen: fueller(rest.join("<<")) };
 76	}
