 78	/**
 79	 * Datum JJMMTT → ISO. `art`: „geburt“ (Jahrhundert so, dass das Datum nicht in der Zukunft liegt) oder
 80	 * „ablauf“ (Jahrhundert so, dass das Datum höchstens 50 Jahre zurück liegt).
 81	 */
 82	export function mrzDatum(jjmmtt, art = "geburt", heute = new Date()) {
 83	  if (!/^\d{6}$/.test(String(jjmmtt || ""))) return null;
 84	  const jj = Number(jjmmtt.slice(0, 2));
 85	  const mm = Number(jjmmtt.slice(2, 4));
 86	  const tt = Number(jjmmtt.slice(4, 6));
 87	  if (mm < 1 || mm > 12 || tt < 1 || tt > 31) return null;
 88	  const jetztJ = heute.getUTCFullYear() % 100;
 89	  let jahr;
 90	  if (art === "geburt") jahr = jj > jetztJ ? 1900 + jj : 2000 + jj;
 91	  else jahr = jj >= jetztJ + 50 ? 1900 + jj : 2000 + jj;
 92	  const iso = `${jahr}-${String(mm).padStart(2, "0")}-${String(tt).padStart(2, "0")}`;
 93	  const d = new Date(`${iso}T00:00:00Z`);
 94	  if (Number.isNaN(d.getTime()) || d.getUTCDate() !== tt) return null;
 95	  return iso;
 96	}
