 98	const DOKUMENTART = { P: "Reisepass", I: "Personalausweis", A: "Ausweis", C: "Ausweis", V: "Visum" };
 99	
100	/**
101	 * MRZ zerlegen und alle Prüfziffern prüfen.
102	 * Liefert { ok, format, fehler[], felder{…}, pruefungen[{feld,label,ok}] } – `ok` = Format gültig UND alle Prüfziffern stimmen.
103	 */
104	export function mrzPruefen(eingabe, { heute = new Date() } = {}) {
105	  const zeilen = Array.isArray(eingabe) ? eingabe.map((z) => String(z).toUpperCase().replace(/\s+/g, "")) : mrzNormalisieren(eingabe);
106	  const format = mrzFormat(zeilen);
