184	/** Name in MRZ-Schreibweise (ICAO 9303-3 Transliteration: Ä → AE, Ö → OE, Ü → UE, ß → SS; Akzente entfernt) */
185	export function mrzName(s) {
186	  return String(s || "")
187	    .toUpperCase()
188	    .replace(/Ä/g, "AE").replace(/Ö/g, "OE").replace(/Ü/g, "UE").replace(/ẞ|ß/g, "SS")
189	    .normalize("NFKD").replace(/[̀-ͯ]/g, "")
190	    .replace(/[^A-Z]+/g, " ")
191	    .replace(/\s+/g, " ")
192	    .trim();
193	}
194	
195	const tokens = (s) => mrzName(s).split(" ").filter((t) => t.length > 1 || /^[A-Z]$/.test(t));
196	
197	/** Nachname vollständig enthalten, erster Vorname enthalten (MRZ kürzt lange Namen – Präfixe zählen) */
198	export function nameStimmt({ vorname = "", nachname = "" } = {}, felder = {}) {
199	  const mrzNach = tokens(felder.nachname);
200	  const mrzVor = tokens(felder.vornamen);
201	  const sollNach = tokens(nachname);
202	  const sollVor = tokens(vorname);
203	  if (!sollNach.length || !mrzNach.length) return false;
204	  const nachOk = sollNach.every((t) => mrzNach.some((m) => m === t || (m.length >= 3 && t.startsWith(m))));
205	  const vorOk = !sollVor.length || mrzVor.some((m) => m === sollVor[0] || (m.length >= 3 && sollVor[0].startsWith(m)));
206	  return nachOk && vorOk;
207	}
