209	const tageBis = (iso, heute = new Date()) =>
210	  iso ? Math.floor((new Date(`${iso}T00:00:00Z`).getTime() - new Date(`${heute.toISOString().slice(0, 10)}T00:00:00Z`).getTime()) / 86400000) : null;
211	
212	/** Dokumentnummer für Anzeigen und Protokolle: nur die letzten 3 Zeichen */
213	export const nummerMaskiert = (n) => (n ? `${"•".repeat(Math.max(0, String(n).length - 3))}${String(n).slice(-3)}` : "");
