215	/**
216	 * Vorprüfung: Prüfziffern + Ablauf + Abgleich mit den Angaben im Konto/KYC-Fall.
217	 * soll: { vorname, nachname, geburtsdatum (ISO), staatsangehoerigkeit? (ISO-2), ausweisNummer? }
218	 * Liefert { ergebnis: plausibel|auffaellig|ungueltig, text, hinweise[], mrz, abgleich{…}, tageGueltig }
219	 *   plausibel  – alle Prüfziffern ok, nicht abgelaufen, Name und Geburtsdatum stimmen
220	 *   auffaellig – Prüfziffern ok, aber abgelaufen oder Abweichung zu den Angaben
221	 *   ungueltig  – Format/Prüfziffer falsch (vermutlich Tippfehler oder manipuliert)
222	 */
223	export function mrzVorpruefung(eingabe, soll = {}, { heute = new Date() } = {}) {
224	  const mrz = mrzPruefen(eingabe, { heute });
225	  const hinweise = [];
226	  if (!mrz.ok) {
227	    return { ergebnis: "ungueltig", text: "Die maschinenlesbare Zone ist nicht stimmig.", hinweise: mrz.fehler, mrz, abgleich: {}, tageGueltig: null };
228	  }
229	  const f = mrz.felder;
230	  const tageGueltig = tageBis(f.gueltigBis, heute);
231	  const abgleich = {
232	    name: soll.nachname ? nameStimmt(soll, f) : null,
233	    geburtsdatum: soll.geburtsdatum ? String(soll.geburtsdatum).slice(0, 10) === f.geburtsdatum : null,
234	    gueltig: tageGueltig !== null && tageGueltig >= 0,
235	    ausweisNummer: soll.ausweisNummer ? mrzName(soll.ausweisNummer).replace(/\s/g, "") === f.dokumentnummer : null,
236	  };
237	  if (!abgleich.gueltig) hinweise.push(`Das Dokument ist seit ${Math.abs(tageGueltig)} Tagen abgelaufen (gültig bis ${f.gueltigBis}).`);
238	  else if (tageGueltig < 30) hinweise.push(`Das Dokument läuft in ${tageGueltig} Tagen ab.`);
239	  if (abgleich.name === false) hinweise.push("Der Name in der MRZ weicht von den Angaben im Konto ab.");
240	  if (abgleich.geburtsdatum === false) hinweise.push("Das Geburtsdatum in der MRZ weicht von den Angaben ab.");
241	  if (abgleich.ausweisNummer === false) hinweise.push("Die Dokumentnummer weicht von der angegebenen Ausweisnummer ab.");
242	  if (abgleich.name === null || abgleich.geburtsdatum === null) hinweise.push("Für einen vollständigen Abgleich fehlen Name oder Geburtsdatum in Ihren Angaben.");
243	  const auffaellig = !abgleich.gueltig || abgleich.name === false || abgleich.geburtsdatum === false || abgleich.ausweisNummer === false;
244	  return {
245	    ergebnis: auffaellig ? "auffaellig" : "plausibel",
246	    text: auffaellig ? "Prüfziffern stimmen, es gibt aber Abweichungen – die Compliance prüft manuell." : "Automatisch plausibel: Prüfziffern, Gültigkeit und Abgleich ohne Auffälligkeit. Die Identifizierung selbst erfolgt durch den Anbieter bzw. die Compliance.",
247	    hinweise,
248	    mrz,
249	    abgleich,
250	    tageGueltig,
251	  };
252	}
