 50	/** UID CH: Prüfziffer (Modulo 11, Gewichte 5 4 3 2 7 6 5 4) – eCH-0097 */
 51	export function uidChPruefen(uid) {
 52	  const z = String(uid || "").replace(/\D/g, "");
 53	  if (z.length !== 9) return false;
 54	  const g = [5, 4, 3, 2, 7, 6, 5, 4];
 55	  const s = g.reduce((a, w, i) => a + w * Number(z[i]), 0);
 56	  let p = 11 - (s % 11);
 57	  if (p === 11) p = 0;
 58	  if (p === 10) return false;
 59	  return p === Number(z[8]);
 60	}
