 68	export function firmaNormalisieren(s) {
 69	  let t = String(s || "")
 70	    .toLowerCase()
 71	    .replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
 72	    .normalize("NFKD").replace(/[̀-ͯ]/g, "")
 73	    .replace(/\((demo|fiktiv|test)\)/g, " ")
 74	    .replace(/[^a-z0-9]+/g, " ");
 75	  for (const re of RECHTSFORM_PHRASEN) t = t.replace(re, " ");
