 79	const bigramme = (s) => {
 80	  const t = ` ${s} `;
 81	  const m = new Map();
 82	  for (let i = 0; i < t.length - 1; i++) m.set(t.slice(i, i + 2), (m.get(t.slice(i, i + 2)) || 0) + 1);
 83	  return m;
 84	};
