 86	/** Ähnlichkeit 0–1 (Dice-Koeffizient über Buchstabenpaare der normalisierten Namen) */
 87	export function namensAehnlichkeit(a, b) {
 88	  const x = firmaNormalisieren(a);
 89	  const y = firmaNormalisieren(b);
 90	  if (!x || !y) return 0;
 91	  if (x === y) return 1;
 92	  const A = bigramme(x);
 93	  const B = bigramme(y);
 94	  let schnitt = 0;
 95	  let summe = 0;
 96	  for (const [k, n] of A) {
 97	    schnitt += Math.min(n, B.get(k) || 0);
 98	    summe += n;
 99	  }
100	  for (const n of B.values()) summe += n;
101	  return summe ? (2 * schnitt) / summe : 0;
102	}
