107	  de_gmbh: /\bGmbH\b|Gesellschaft mit beschränkter Haftung/i,
108	  de_ug: /UG \(haftungsbeschränkt\)|Unternehmergesellschaft \(haftungsbeschränkt\)/i,
109	  de_gmbh_co_kg: /GmbH\s?&\s?Co\.?\s?KG/i,
