115	/**
116	 * Firmennamen-Vorprüfung. treffer: Registertreffer [{ name, nummer, status }] der Suche.
117	 * Liefert { ergebnis: frei|aehnlich|belegt|unzulaessig, hinweise[], aehnlich[{name,nummer,aehnlichkeit}] }
118	 */
119	export function firmennamePruefen(name, rechtsform, treffer = []) {
120	  const n = String(name || "").trim();
121	  const hinweise = [];
122	  if (n.length < 3) return { ergebnis: "unzulaessig", hinweise: ["Bitte geben Sie einen Firmennamen an."], aehnlich: [] };
123	  if (ZUSATZ[rechtsform] && !ZUSATZ[rechtsform].test(n)) hinweise.push("Der Rechtsformzusatz fehlt oder passt nicht zur gewählten Rechtsform (z. B. „GmbH“ bzw. „GmbH & Co. KG“).");
124	  if (IRREFUEHREND.some((re) => re.test(n))) hinweise.push("Der Name enthält Begriffe, die in der Regel geschützt sind oder irreführen können (z. B. Bank, Versicherung, amtlich klingende Zusätze).");
125	  if (firmaNormalisieren(n).length < 3) hinweise.push("Der Name braucht einen unterscheidungskräftigen Bestandteil neben dem Rechtsformzusatz.");
126	  const aehnlich = treffer
127	    .map((t) => ({ name: t.name, nummer: t.nummer || "", sitz: t.sitz || "", status: t.status || "", aehnlichkeit: Math.round(namensAehnlichkeit(n, t.name) * 100) / 100 }))
128	    .filter((t) => t.aehnlichkeit >= 0.6)
129	    .sort((a, b) => b.aehnlichkeit - a.aehnlichkeit)
130	    .slice(0, 8);
131	  let ergebnis = "frei";
132	  if (aehnlich.some((t) => t.aehnlichkeit >= 0.95 && t.status !== "geloescht")) ergebnis = "belegt";
133	  else if (aehnlich.length) ergebnis = "aehnlich";
134	  if (hinweise.length && ergebnis !== "belegt") ergebnis = "unzulaessig"; // unzulässiger Name hat Vorrang vor „ähnlich“
135	  if (ergebnis === "belegt") hinweise.unshift("Ein gleichlautender Name ist bereits eingetragen – bitte einen anderen Namen wählen.");
136	  if (ergebnis === "aehnlich") hinweise.unshift("Es gibt ähnliche Namen. Am Sitz muss sich die Firma deutlich unterscheiden (Firmenausschließlichkeit) – Abstimmung mit dem Notariat empfohlen.");
137	  return { ergebnis, hinweise, aehnlich };
138	}
