181	async function holen(url, init = {}, { versuche = 2 } = {}) {
182	  for (let i = 1; ; i++) {
183	    let res;
184	    try {
185	      res = await fetch(url, { ...init, signal: AbortSignal.timeout(15000), cache: "no-store" });
186	    } catch {
187	      if (i < versuche) continue;
188	      throw Object.assign(new Error("Das Register ist derzeit nicht erreichbar. Bitte später erneut versuchen."), { status: 502 });
189	    }
190	    if (res.status >= 500 && i < versuche) continue;
191	    if (res.status === 404) return null;
192	    if (res.status === 401 || res.status === 403) throw Object.assign(new Error("Zugang zum Register abgelehnt – Zugangsdaten prüfen."), { status: 502 });
193	    if (!res.ok) throw Object.assign(new Error(`Registerabfrage fehlgeschlagen (HTTP ${res.status}).`), { status: 502 });
194	    return res.json().catch(() => null);
195	  }
196	}
