267	function demoSuche(land, q) {
268	  const alle = demoBestand().filter((f) => f.land === land);
269	  const n = firmaNormalisieren(q);
270	  return alle
271	    .map((f) => ({ f, s: firmaNormalisieren(f.name).includes(n) ? 1 : namensAehnlichkeit(q, f.name) }))
272	    .filter((x) => x.s >= 0.45)
273	    .sort((a, b) => b.s - a.s)
274	    .map(({ f }) => ({ name: f.name, nummer: f.nummer, sitz: f.sitz, rechtsform: f.rechtsform, status: f.status, demo: !f.echt }));
275	}
