277	function demoFirma(land, nummer) {
278	  const f = demoBestand().find((x) => x.land === land && x.nummer.toLowerCase() === nummer.toLowerCase());
279	  return f ? { ...f, stand: new Date().toISOString().slice(0, 10), demo: true } : null;
