284	/** Firmensuche. Liefert { quelle, treffer[], hinweis } */
285	export async function registerSuchen({ land, q }, env = process.env) {
286	  if (!REGISTER_LAENDER[land]) throw Object.assign(new Error("Unbekanntes Land."), { status: 422 });
287	  const text = String(q || "").trim().slice(0, 120);
288	  if (text.length < 2) throw Object.assign(new Error("Bitte mindestens 2 Zeichen eingeben."), { status: 422 });
289	  const k = registerKonfig(env);
290	  const kl = k[land];
291	  if (land === "CH" && kl.aktiv) return { quelle: "zefix", treffer: await zefixSuche(kl, text), hinweis: "" };
292	  if (land !== "CH" && kl.aktiv) return { quelle: land === "AT" ? "firmenbuch" : "handelsregister", treffer: await vertragSuche(kl, text), hinweis: "" };
293	  if (!k.demoErlaubt) throw Object.assign(new Error(`Die Anbindung an das ${REGISTER_LAENDER[land].register} ist nicht konfiguriert.`), { status: 503 });
294	  return { quelle: "demo", treffer: demoSuche(land, text), hinweis: `Demo-Daten – keine Live-Abfrage (${REGISTER_LAENDER[land].abruf}).` };
295	}
