297	/** Firmendaten per Registernummer. Liefert { quelle, firma|null, abrufAm } */
298	export async function registerAbrufen({ land, nummer }, env = process.env) {
299	  const p = registernummerPruefen(land, nummer);
300	  if (!p.ok) throw Object.assign(new Error(p.fehler), { status: 422 });
301	  const k = registerKonfig(env);
302	  const kl = k[land];
303	  const abrufAm = new Date().toISOString();
304	  if (land === "CH" && kl.aktiv) return { quelle: "zefix", firma: await zefixFirmaAbrufen(kl, p.nummer), abrufAm };
305	  if (land !== "CH" && kl.aktiv) return { quelle: land === "AT" ? "firmenbuch" : "handelsregister", firma: await vertragFirma(kl, p.nummer), abrufAm };
306	  if (!k.demoErlaubt) throw Object.assign(new Error(`Die Anbindung an das ${REGISTER_LAENDER[land].register} ist nicht konfiguriert.`), { status: 503 });
307	  return { quelle: "demo", firma: demoFirma(land, p.nummer), abrufAm };
308	}

