 47	/**
 48	 * Anbieterwert → Ampel. Richtwerte (anbieterübliche Klassen, vor Einsatz mit dem Vertrag abstimmen):
 49	 *   Creditreform-Index / Demo: ≤ 250 grün, ≤ 350 gelb, sonst rot (≥ 500 = massive Zahlungsstörungen)
 50	 *   KSV1870-Rating:            ≤ 299 grün, ≤ 399 gelb, sonst rot
 51	 *   D&B Failure Score (1–100): ≥ 51 grün, ≥ 21 gelb, sonst rot
 52	 */
 53	export function bonitaetAmpel(anbieter, score) {
 54	  const s = Number(score);
 55	  if (!Number.isFinite(s)) return "unbekannt";
 56	  if (anbieter === "ksv1870") return s <= 299 ? "gruen" : s <= 399 ? "gelb" : "rot";
 57	  if (anbieter === "dnb") return s >= 51 ? "gruen" : s >= 21 ? "gelb" : "rot";
 58	  if (anbieter === "crif") return s >= 600 ? "gruen" : s >= 450 ? "gelb" : "rot"; // CRIF-Scores: hoch = gut (produktabhängig)
 59	  return s <= 250 ? "gruen" : s <= 350 ? "gelb" : "rot";
 60	}
