 62	export function bonitaetEinstellungenStandard() {
 63	  return {
 64	    geltung: null, // null = aus Umgebung (PLATTFORM_BONITAET_VOR_LOI); "alle" | "firmen" | "pilot" | "aus"
 65	    pilotKonten: [],
 66	    gueltigTage: 180, // so lange gilt eine Auskunft für LOI/Gebot
 67	    rotSperrt: true, // rote Ampel sperrt bis zur manuellen Freigabe
 68	    schritte: { loi: true, gebot: true },
 69	  };
