 72	/** Geltung: Einstellung > Umgebung > Standard (Produktion „firmen“, Entwicklung „pilot“) */
 73	export function bonitaetGeltung(einstellungen = {}, env = {}) {
 74	  const e = einstellungen?.geltung;
 75	  if (["alle", "firmen", "pilot", "aus"].includes(e)) return e;
 76	  const u = String(env.PLATTFORM_BONITAET_VOR_LOI || "").toLowerCase();
 77	  if (["alle", "firmen", "pilot", "aus"].includes(u)) return u;
 78	  return env.NODE_ENV === "production" ? "firmen" : "pilot";
 79	}
