 81	/** Ist die Bonitätsprüfung für dieses Subjekt Pflicht? (firma = Investor handelt als Unternehmen) */
 82	export function bonitaetPflichtAktiv(schritt, { kontoId, firma }, einstellungen = bonitaetEinstellungenStandard(), env = {}) {
 83	  const e = { ...bonitaetEinstellungenStandard(), ...(einstellungen || {}) };
 84	  if (e.schritte?.[schritt] === false) return false;
 85	  const g = bonitaetGeltung(e, env);
 86	  if (g === "aus") return false;
 87	  if (g === "alle") return true;
 88	  if (g === "firmen") return !!firma;
 89	  return !!firma && (e.pilotKonten || []).includes(kontoId); // pilot
 90	}
