 92	/** Gültige Auskunft? a: Auskunft oder null. Liefert { ok, grund } */
 93	export function bonitaetGueltig(a, einstellungen = bonitaetEinstellungenStandard(), jetzt = new Date()) {
 94	  const e = { ...bonitaetEinstellungenStandard(), ...(einstellungen || {}) };
 95	  if (!a) return { ok: false, grund: "fehlt" };
 96	  if (a.status !== "abgeschlossen" && a.status !== "keine_daten") return { ok: false, grund: "offen" };
 97	  const alter = (jetzt.getTime() - new Date(a.auskunftAm || a.am).getTime()) / 86400000;
 98	  if (!(alter <= e.gueltigTage)) return { ok: false, grund: "veraltet" };
 99	  if (a.status === "keine_daten" && !a.freigabe) return { ok: false, grund: "keine_daten" };
100	  if (a.ampel === "rot" && e.rotSperrt && !a.freigabe) return { ok: false, grund: "rot" };
101	  return { ok: true, grund: "" };
102	}
