 19	export function bonitaetKonfig(env = process.env) {
 20	  const prod = env.NODE_ENV === "production";
 21	  const a = String(env.BONITAET_ANBIETER || "").toLowerCase();
 22	  const anbieter = BONITAET_ANBIETER[a] ? a : prod ? "" : "demo";
 23	  return {
 24	    anbieter,
 25	    label: BONITAET_ANBIETER[anbieter]?.label || "nicht konfiguriert",
 26	    url: String(env.BONITAET_API_URL || "").replace(/\/$/, ""),
 27	    key: String(env.BONITAET_API_KEY || ""),
 28	    produkt: String(env.BONITAET_PRODUKT || ""),
 29	    aktiv: anbieter === "demo" ? !prod || env.PLATTFORM_DEMO === "1" : !!(env.BONITAET_API_URL && env.BONITAET_API_KEY),
 30	    demo: anbieter === "demo",
