 36	async function extern(k, daten) {
 37	  for (let i = 1; ; i++) {
 38	    let res;
 39	    try {
 40	      res = await fetch(`${k.url}/auskunft`, {
 41	        method: "POST",
 42	        headers: { Authorization: `Bearer ${k.key}`, "Content-Type": "application/json", Accept: "application/json" },
 43	        body: JSON.stringify({ ...daten, produkt: k.produkt || undefined }),
 44	        signal: AbortSignal.timeout(20000),
 45	        cache: "no-store",
 46	      });
 47	    } catch {
 48	      if (i < 2) {
 49	        await warte(1500);
 50	        continue;
 51	      }
 52	      throw Object.assign(new Error("Die Auskunftei ist derzeit nicht erreichbar."), { status: 502 });
 53	    }
 54	    if (res.status >= 500 && i < 2) {
 55	      await warte(1500);
 56	      continue;
 57	    }
 58	    if (!res.ok) throw Object.assign(new Error(`Die Auskunftei hat die Anfrage abgelehnt (HTTP ${res.status}).`), { status: 502 });
 59	    return res.json();
 60	  }
 61	}
