 63	/** Deterministischer Simulator: gleiche Firma → gleiche Auskunft. „Insolvent/Liquidation“ im Namen → rot. */
 64	function demoAuskunft({ name, land }) {
 65	  const h = createHash("sha256").update(String(name).toLowerCase()).digest();
 66	  const kritisch = /insolven|liquidation|konkurs/i.test(name);
 67	  const score = kritisch ? 520 + (h[0] % 60) : 140 + ((h[0] * 7 + h[1]) % 230); // 140–369
 68	  const pd = Math.round((kritisch ? 0.18 + (h[2] % 10) / 100 : 0.002 + (score - 140) / 9000) * 1000) / 1000;
 69	  const limit = kritisch ? 0 : Math.round((250000 + (h[3] % 40) * 125000) / 5000) * 5000;
 70	  return {
 71	    status: "abgeschlossen",
 72	    score,
 73	    skala: BONITAET_ANBIETER.demo.skala,
 74	    kreditlimit: limit,
 75	    waehrung: land === "CH" ? "CHF" : "EUR",
 76	    ausfallwahrscheinlichkeit: pd,
 77	    zahlungsweise: kritisch ? "Zahlungsstörungen bekannt" : score <= 250 ? "innerhalb vereinbarter Ziele" : "gelegentlich verzögert",
 78	    negativmerkmale: kritisch ? ["Insolvenzverfahren eröffnet (Demo)"] : [],
 79	    referenz: `DEMO-${h.toString("hex").slice(0, 10).toUpperCase()}`,
 80	    auskunftAm: new Date().toISOString(),
 81	  };
 82	}
