 84	/**
 85	 * Auskunft einholen. subjekt: { name, land, registernummer, anschrift }
 86	 * Liefert normalisiert { anbieter, anbieterLabel, status, score, skala, ampel, kreditlimit, waehrung, ausfallwahrscheinlichkeit,
 87	 *   zahlungsweise, negativmerkmale[], referenz, auskunftAm, demo, pdfBase64? }
 88	 */
 89	export async function bonitaetAbrufen(subjekt, env = process.env) {
 90	  const k = bonitaetKonfig(env);
 91	  if (!k.anbieter || !k.aktiv) throw Object.assign(new Error("Die Bonitätsauskunft ist nicht konfiguriert (Vertrag mit einer Auskunftei erforderlich)."), { status: 503 });
 92	  const daten = { land: subjekt.land, name: subjekt.name, registernummer: subjekt.registernummer || "", anschrift: subjekt.anschrift || "" };
 93	  const r = k.demo ? demoAuskunft(daten) : await extern(k, daten);
 94	  const status = r?.status === "keine_daten" ? "keine_daten" : "abgeschlossen";
 95	  const score = Number.isFinite(Number(r?.score)) ? Number(r.score) : null;
 96	  return {
 97	    anbieter: k.anbieter,
 98	    anbieterLabel: k.label,
 99	    status,
100	    score,
101	    skala: String(r?.skala || BONITAET_ANBIETER[k.anbieter]?.skala || "").slice(0, 120),
102	    ampel: status === "keine_daten" ? "unbekannt" : bonitaetAmpel(k.anbieter, score),
103	    kreditlimit: Number.isFinite(Number(r?.kreditlimit)) ? Number(r.kreditlimit) : null,
104	    waehrung: /^[A-Z]{3}$/.test(String(r?.waehrung || "")) ? r.waehrung : "EUR",
105	    ausfallwahrscheinlichkeit: Number.isFinite(Number(r?.ausfallwahrscheinlichkeit)) ? Number(r.ausfallwahrscheinlichkeit) : null,
106	    zahlungsweise: String(r?.zahlungsweise || "").slice(0, 160),
107	    negativmerkmale: (Array.isArray(r?.negativmerkmale) ? r.negativmerkmale : []).slice(0, 10).map((x) => String(x).slice(0, 200)),
108	    referenz: String(r?.referenz || "").slice(0, 80),
109	    auskunftAm: r?.auskunftAm && !Number.isNaN(Date.parse(r.auskunftAm)) ? new Date(r.auskunftAm).toISOString() : new Date().toISOString(),
110	    demo: k.demo,
111	    pdfBase64: typeof r?.pdfBase64 === "string" && r.pdfBase64.length < 8_000_000 ? r.pdfBase64 : null,
112	  };
113	}

