   107	// Zustand am Konto (Demo: nutzer.onboardingPfade, Frappe: Plattform Konto.onboarding_pfade, JSON):
   108	//   { aktiv: pfadId, pfade: { [pfadId]: { untertyp, bestaetigt[], spaeter[], gestartetAm, abgeschlossenAm } },
   109	//     tour: { aus, gesehen[] }, mails: { willkommen, erinnerung3, erinnerung7 }, auswertung: {…Snapshot}, aktualisiertAm }
