   121	/** Wert eines Fakts über Punktpfad („kyc.status“) */
   122	export function faktWert(fakten, pfad) {
   123	  let w = fakten;
   124	  for (const teil of String(pfad || "").split(".")) {
   125	    if (w === null || w === undefined || typeof w !== "object") return undefined;
   126	    w = w[teil];
   127	  }
   128	  return w;
   129	}
   130	
   131	const wahr = (w) => (Array.isArray(w) ? w.length > 0 : istZahl(w) ? w > 0 : !!w);
   132	
   133	/** Kriterium auswerten. kontext: { fakten, bestaetigt: Set|[], untertyp } */
   134	export function kriteriumErfuellt(k, kontext, schrittId = null) {
   135	  if (!k || typeof k !== "object") return false;
   136	  const { fakten = {}, untertyp = null } = kontext;
   137	  const bestaetigt = kontext.bestaetigt instanceof Set ? kontext.bestaetigt : new Set(kontext.bestaetigt || []);
   138	  if (Array.isArray(k.alle)) return k.alle.every((x) => kriteriumErfuellt(x, kontext, schrittId));
   139	  if (Array.isArray(k.eines)) return k.eines.some((x) => kriteriumErfuellt(x, kontext, schrittId));
   140	  if (k.nicht) return !kriteriumErfuellt(k.nicht, kontext, schrittId);
   141	  if (k.merker) return !!schrittId && bestaetigt.has(schrittId);
   142	  if (Array.isArray(k.untertyp)) return !!untertyp && k.untertyp.includes(untertyp);
   143	  if (typeof k.fakt === "string") {
   144	    const w = faktWert(fakten, k.fakt);
   145	    if (Array.isArray(k.in)) return k.in.includes(w);
   146	    if (istZahl(k.min)) return istZahl(w) ? w >= k.min : false;
   147	    return wahr(w);
   148	  }
   149	  return false;
   150	}
