   152	/** Gilt ein Schritt für diesen Untertyp? (nurFuer: [untertypen]) */
   153	export const schrittGilt = (s, untertyp) => !Array.isArray(s.nurFuer) || (!!untertyp && s.nurFuer.includes(untertyp)) || (!untertyp && s.nurFuer.includes("*"));
   154	
   155	/** Pflicht für diesen Untertyp? (true | false | [untertypen]) */
   156	export const schrittPflicht = (s, untertyp) => (Array.isArray(s.pflicht) ? !!untertyp && s.pflicht.includes(untertyp) : !!s.pflicht);
   157	
   158	/** Text/Punkte je Untertyp auflösen */
   159	function aufloesen(s, untertyp) {
   160	  const t = (s.texte && untertyp && s.texte[untertyp]) || s.text || "";
   161	  const punkte = [...(s.punkte || []), ...((s.punkteJe && untertyp && s.punkteJe[untertyp]) || [])];
   162	  const links = [...((s.linksJe && untertyp && s.linksJe[untertyp]) || []), ...(s.links || [])];
   163	  return { text: t, punkte, links };
   164	}
