   166	/** Leerer Zustand */
   167	export function pfadZustandLeer() {
   168	  return { aktiv: null, pfade: {}, tour: { aus: false, gesehen: [] }, mails: {}, auswertung: null, aktualisiertAm: null };
   169	}
