   171	const idListe = (x, max = 60) => (Array.isArray(x) ? [...new Set(x.filter((y) => typeof y === "string" && ID_MUSTER.test(y)))].slice(0, max) : []);
   172	const zeit = (x) => (typeof x === "string" && x.length <= 40 && !Number.isNaN(Date.parse(x)) ? x : null);
