   174	/** Gespeicherten Zustand bereinigen (Positivliste, Format – Server und Browser) */
   175	export function pfadZustandBereinigen(roh) {
   176	  const o = roh && typeof roh === "object" && !Array.isArray(roh) ? roh : {};
   177	  const z = pfadZustandLeer();
   178	  z.aktiv = typeof o.aktiv === "string" && ID_MUSTER.test(o.aktiv) ? o.aktiv : null;
   179	  for (const [id, p] of Object.entries(o.pfade && typeof o.pfade === "object" ? o.pfade : {}).slice(0, 12)) {
   180	    if (!ID_MUSTER.test(id) || !p || typeof p !== "object") continue;
   181	    z.pfade[id] = {
   182	      untertyp: typeof p.untertyp === "string" && ID_MUSTER.test(p.untertyp) ? p.untertyp : null,
   183	      bestaetigt: idListe(p.bestaetigt),
   184	      spaeter: idListe(p.spaeter),
   185	      gestartetAm: zeit(p.gestartetAm),
   186	      abgeschlossenAm: zeit(p.abgeschlossenAm),
   187	    };
   188	  }
   189	  const t = o.tour && typeof o.tour === "object" ? o.tour : {};
   190	  z.tour = { aus: t.aus === true, gesehen: idListe(t.gesehen, 80) };
   191	  const m = o.mails && typeof o.mails === "object" ? o.mails : {};
   192	  z.mails = Object.fromEntries(["willkommen", "erinnerung3", "erinnerung7"].filter((k) => zeit(m[k])).map((k) => [k, m[k]]));
   193	  const a = o.auswertung && typeof o.auswertung === "object" ? o.auswertung : null;
   194	  z.auswertung = a && typeof a.pfad === "string" && ID_MUSTER.test(a.pfad)
   195	    ? { pfad: a.pfad, untertyp: typeof a.untertyp === "string" && ID_MUSTER.test(a.untertyp) ? a.untertyp : null, erledigt: istZahl(a.erledigt) ? a.erledigt : 0, gesamt: istZahl(a.gesamt) ? a.gesamt : 0, pflichtOffen: idListe(a.pflichtOffen), quote: istZahl(a.quote) ? a.quote : 0, abgeschlossen: a.abgeschlossen === true, am: zeit(a.am) }
   196	    : null;
   197	  z.aktualisiertAm = zeit(o.aktualisiertAm);
   198	  return z;
   199	}
