   201	/**
   202	 * Pfad für Anzeige und Prüfung auswerten.
   203	 * @param pfad     Definition (pfade/*.js)
   204	 * @param fakten   Fakten aus echten Daten (server/onboarding.js bzw. Frappe)
   205	 * @param zustand  Pfad-Zustand ({ untertyp, bestaetigt, spaeter, abgeschlossenAm })
   206	 * @param optionen { untertypVorschlag, legacyMerker: [ids] } – Vorschlag aus Daten (z. B. Investorentyp im Suchprofil)
   207	 */
   208	export function pfadAuswerten(pfad, fakten = {}, zustand = {}, { untertypVorschlag = null, legacyMerker = [] } = {}) {
   209	  const untertypen = pfad.untertypen || null;
   210	  const gewaehlt = zustand?.untertyp && untertypen?.[zustand.untertyp] ? zustand.untertyp : null;
   211	  const vorschlag = untertypVorschlag && untertypen?.[untertypVorschlag] ? untertypVorschlag : null;
   212	  const untertyp = gewaehlt || vorschlag || null;
   213	  const bestaetigt = new Set([...(zustand?.bestaetigt || []), ...legacyMerker]);
   214	  const spaeter = new Set(zustand?.spaeter || []);
   215	  const kontext = { fakten: { ...fakten, untertyp }, bestaetigt, untertyp };
   216	  const schritte = pfad.schritte
   217	    .filter((s) => schrittGilt(s, untertyp))
   218	    .map((s) => {
   219	      const erledigt = kriteriumErfuellt(s.kriterium, kontext, s.id);
   220	      const { text, punkte, links } = aufloesen(s, untertyp);
   221	      return {
   222	        id: s.id, titel: s.titel, kurz: s.kurz || s.titel, art: s.art || "info", formular: s.formular || null, text, punkte, links,
   223	        begriff: s.begriff || null, firmaLabel: s.firmaLabel || null, pflicht: schrittPflicht(s, untertyp), bestaetigbar: !!s.bestaetigbar, bestaetigenText: s.bestaetigenText || null,
   224	        erledigt, spaeter: !erledigt && spaeter.has(s.id),
   225	      };
   226	    });
   227	  const erledigtAnzahl = schritte.filter((s) => s.erledigt).length;
   228	  const pflichtOffen = schritte.filter((s) => s.pflicht && !s.erledigt).map((s) => s.id);
   229	  return {
   230	    id: pfad.id, titel: pfad.titel, text: pfad.text, gruppe: pfad.gruppe || "extern",
   231	    untertyp, untertypGewaehlt: !!gewaehlt, untertypen: untertypen ? Object.entries(untertypen).map(([id, u]) => ({ id, label: u.label, text: u.text || "" })) : [],
   232	    schritte, erledigt: erledigtAnzahl, gesamt: schritte.length, quote: schritte.length ? Math.round((erledigtAnzahl / schritte.length) * 100) : 100,
   233	    pflichtOffen, abschliessbar: pflichtOffen.length === 0, abgeschlossen: !!zustand?.abgeschlossenAm && pflichtOffen.length === 0,
   234	    abgeschlossenAm: zustand?.abgeschlossenAm || null, naechster: (schritte.find((s) => !s.erledigt && !s.spaeter) || schritte.find((s) => !s.erledigt) || null)?.id || null,
   235	  };
   236	}
