   243	/**
   244	 * Änderung prüfen und anwenden (Server). Wirft { status, meldung } als Fehlerobjekt über `fehler(status, meldung)`.
   245	 * aktion: { aktion: pfad|untertyp|bestaetigen|spaeter|fortsetzen|abschliessen|tour, pfad?, untertyp?, schritt?, aus?, gesehen? }
   246	 * erlaubt: { pfade: [Definitionen, die das Konto nutzen darf], untertypErlaubt?: (pfad, untertyp) => bool, auswertung?: (pfadId) => Auswertung, touren: {id:…} }
   247	 */
   248	export function aenderungPruefen(zustandRoh, aktion, erlaubt, fehler, am = new Date().toISOString()) {
   249	  const z = pfadZustandBereinigen(zustandRoh);
   250	  const a = aktion && typeof aktion === "object" ? aktion : {};
   251	  const art = String(a.aktion || "");
   252	  const pfadDef = (id) => erlaubt.pfade.find((p) => p.id === id) || null;
   253	  const pz = (id) => (z.pfade[id] ||= { untertyp: null, bestaetigt: [], spaeter: [], gestartetAm: am, abgeschlossenAm: null });
   254	
   255	  if (art === "tour") {
   256	    if (a.aus !== undefined) {
   257	      if (typeof a.aus !== "boolean") throw fehler(422, "Ungültige Angabe zur Tour.");
   258	      z.tour.aus = a.aus;
   259	    }
   260	    if (a.gesehen !== undefined) {
   261	      if (typeof a.gesehen !== "string" || !erlaubt.touren?.[a.gesehen]) throw fehler(422, "Unbekannter Tour-Hinweis.");
   262	      if (!z.tour.gesehen.includes(a.gesehen)) z.tour.gesehen.push(a.gesehen);
   263	    }
   264	    z.aktualisiertAm = am;
   265	    return z;
   266	  }
   267	
   268	  const def = pfadDef(String(a.pfad || ""));
   269	  if (!def) throw fehler(403, "Dieser Einstieg passt nicht zu Ihren Rollen.");
   270	  const p = pz(def.id);
   271	
   272	  if (art === "pfad") {
   273	    z.aktiv = def.id;
   274	  } else if (art === "untertyp") {
   275	    const u = String(a.untertyp || "");
   276	    if (!def.untertypen?.[u] || (erlaubt.untertypErlaubt && !erlaubt.untertypErlaubt(def, u))) throw fehler(422, "Diese Auswahl ist für Ihr Konto nicht möglich.");
   277	    p.untertyp = u;
   278	    z.aktiv = def.id;
   279	  } else if (art === "bestaetigen" || art === "spaeter" || art === "fortsetzen") {
   280	    const schritt = String(a.schritt || "");
   281	    const auswertung = erlaubt.auswertung ? erlaubt.auswertung(def.id, p) : null;
   282	    const s = auswertung ? auswertung.schritte.find((x) => x.id === schritt) : def.schritte.find((x) => x.id === schritt);
   283	    if (!s) throw fehler(422, "Diesen Schritt gibt es in Ihrem Einstieg nicht.");
   284	    if (art === "bestaetigen") {
   285	      if (!s.bestaetigbar) throw fehler(422, "Dieser Schritt wird automatisch erledigt, sobald die Angaben vorliegen.");
   286	      if (!p.bestaetigt.includes(schritt)) p.bestaetigt.push(schritt);
   287	      p.spaeter = p.spaeter.filter((x) => x !== schritt);
   288	    } else if (art === "spaeter") {
   289	      if (!p.spaeter.includes(schritt)) p.spaeter.push(schritt);
   290	    } else {
   291	      p.spaeter = p.spaeter.filter((x) => x !== schritt);
   292	    }
   293	    z.aktiv ||= def.id;
   294	  } else if (art === "abschliessen") {
   295	    const auswertung = erlaubt.auswertung ? erlaubt.auswertung(def.id, p) : null;
   296	    if (!auswertung) throw fehler(503, "Der Stand kann gerade nicht geprüft werden.");
   297	    if (auswertung.pflichtOffen.length) {
   298	      const titel = auswertung.schritte.filter((s) => auswertung.pflichtOffen.includes(s.id)).map((s) => s.kurz);
   299	      throw fehler(409, `Noch offen: ${titel.join(", ")}.`);
   300	    }
   301	    p.abgeschlossenAm ||= am;
   302	  } else {
   303	    throw fehler(422, "Unbekannte Aktion.");
   304	  }
   305	  z.aktualisiertAm = am;
   306	  return z;
   307	}
