   309	/** Tour-Hinweis für einen Portalpfad (erster Treffer, längster Präfix zuerst) */
   310	export function tourFuer(touren, pfadname, rollen = []) {
   311	  const kandidaten = Object.entries(touren)
   312	    .filter(([, t]) => (t.exakt ? pfadname === t.pfad : pfadname === t.pfad || pfadname.startsWith(t.pfad + "/")))
   313	    .filter(([, t]) => !t.rollen || t.rollen.some((r) => rollen.includes(r)))
   314	    .sort((a, b) => b[1].pfad.length - a[1].pfad.length);
   315	  return kandidaten.length ? { id: kandidaten[0][0], ...kandidaten[0][1] } : null;
   316	}
