   318	/**
   319	 * Fällige Onboarding-Mail eines Kontos (Willkommen bzw. Erinnerung nach 3/7 Tagen) – oder null.
   320	 * konto: { erstelltAm, checklisteAus }, zustand: bereinigter Pfad-Zustand (mit auswertung-Snapshot)
   321	 */
   322	export function faelligeMail(konto, zustand, jetztMs = Date.now()) {
   323	  const erstellt = Date.parse(konto?.erstelltAm || "");
   324	  if (!Number.isFinite(erstellt)) return null;
   325	  const alterTage = (jetztMs - erstellt) / TAG_MS;
   326	  const m = zustand.mails || {};
   327	  const a = zustand.auswertung;
   328	  if (!m.willkommen) return alterTage <= WILLKOMMEN_MAX_TAGE ? "willkommen" : null;
   329	  if (!a || a.abgeschlossen || !a.pflichtOffen.length || konto.checklisteAus) return null;
   330	  for (const t of [...ERINNERUNG_TAGE].reverse()) {
   331	    const k = `erinnerung${t}`;
   332	    if (alterTage >= t && !m[k]) return alterTage < t + 7 ? k : null; // nur im Zeitfenster – keine Nachholflut
   333	  }
   334	  return null;
   335	}
