    52	  const weiter = {};
    53	  for (const h of ["x-hmac-signature", "x-auth-client", "x-payload-digest", "x-payload-digest-alg", "x-sha2-signature", "x-oekoinvest-signatur", "x-oekoinvest-zeit"]) {
    54	    const w = kopf(h);
