    57	  try {
    58	    const res = await fetch(`${server}/api/method/oekoinvest_app.plattform.api.dienste.webhook_identitaet?anbieter=${encodeURIComponent(anbieter)}`, {
    59	      method: "POST", headers: { ...weiter, "Content-Type": "application/json" }, body: roh, signal: AbortSignal.timeout(15000), cache: "no-store",
    60	    });
    61	    return { status: res.status === 200 ? 200 : res.status === 401 || res.status === 403 ? 401 : res.status === 429 ? 429 : 502, antwort: { ok: res.status === 200 } };
