 34	export function zeitraum({ von, bis } = {}) {
 35	  const heute = tagVon(new Date().toISOString());
 36	  const b = DATUM.test(bis || "") ? bis : heute;
 37	  let vn = DATUM.test(von || "") ? von : null;
