 41	    vn = d.toISOString().slice(0, 10);
 42	  }
 43	  if (vn > b) vn = b;
 44	  const monate = [];
 45	  const d = new Date(`${vn.slice(0, 7)}-01T12:00:00Z`);
 46	  while (d.toISOString().slice(0, 7) <= b.slice(0, 7) && monate.length < 60) {
 47	    monate.push(d.toISOString().slice(0, 7));
 48	    d.setUTCMonth(d.getUTCMonth() + 1);
 49	  }
 50	  return { von: vn, bis: b, monate };
 51	}
