 32	/** Darf dieser Nutzer den Anwendungsfall nutzen? (Admin darf alles) */
 33	export function darfFall(fall, n) {
 34	  const f = ANWENDUNGSFAELLE[fall];
 35	  if (!f || !n) return false;
 36	  const admin = n.rollen?.includes("admin");
 37	  if (admin) return true;
 38	  if (f.admin) return false;
 39	  if (!f.rollen) return true;
 40	  return f.rollen.some((r) => n.rollen?.includes(r));
 41	}
