 47	function text(wert, { min = 0, max, feld }) {
 48	  if (wert === undefined || wert === null) wert = "";
 49	  if (typeof wert !== "string") throw new PlattformFehler(422, `${feld}: ungültige Eingabe.`);
 50	  const t = wert.replace(/\r/g, "").replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, "").trim();
 51	  if (t.length < min) throw new PlattformFehler(422, min > 1 ? `${feld}: bitte mindestens ${min} Zeichen.` : `${feld} fehlt.`);
 52	  if (t.length > max) throw new PlattformFehler(422, `${feld}: höchstens ${max} Zeichen.`);
 53	  return t;
 54	}
