126	/**
127	 * Führt einen Anwendungsfall aus. Liefert ein JSON-Objekt oder eine Streaming-Response.
128	 * `stream` (Body) = true wünscht Streaming; nur für Textfälle im KI-Modus.
129	 */
130	export async function ausfuehren({ fall, nutzer: n, body = {}, backend: b, ip = "" }) {
131	  const def = FAELLE[fall];
132	  if (!def) throw new PlattformFehler(404, "Unbekannter Anwendungsfall.");
133	  if (!darfFall(fall, n)) throw new PlattformFehler(403, "Dieser Assistent steht Ihrer Rolle nicht zur Verfügung.");
134	  limitieren(n, ip);
135	  const eingaben = def.eingaben ? def.eingaben(body) : {};
136	
137	  // Rechteprüfung passiert hier – bei fremden Objekten wird ein 403/404 geworfen, bevor Kontext entsteht
138	  const k = await def.kontext(b, n, body);
139	  const kont = await kontingentPruefen(n);
140	  const quellen = def.quellen ? def.quellen(k, eingaben) : [];
141	  const basis = { ok: true, fall, quellen, kontingent: { limit: kont.limit, rest: Math.max(0, kont.rest - 1) } };
142	  const prot = { fall, objektArt: k.objektArt, objektId: k.objektId };
143	
144	  const regelAntwort = async (hinweis, ergebnis = "ok") => {
145	    await protokollieren(n, { ...prot, modus: "regel", ergebnis });
146	    return { ...basis, modus: "regel", ergebnis: def.regel(k, eingaben), hinweis };
147	  };
148	
149	  if (!kiAktiv()) return regelAntwort(HINWEIS_REGEL);
150	
151	  const anfrage = def.ki(k, eingaben);
152	
153	  // Strukturierte Fälle (Exposé, Triage): eine Anfrage, JSON-Schema
154	  if (def.json) {
155	    try {
156	      const r = await erstellen(anfrage);
157	      await protokollieren(n, { ...prot, modus: "ki", tokensEin: r.nutzung.ein, tokensAus: r.nutzung.aus });
158	      return { ...basis, modus: "ki", ergebnis: def.bereinigen(r.json, k), hinweis: "" };
159	    } catch (e) {
160	      if (!(e instanceof KiFehler)) throw e;
161	      return regelAntwort(e.art === "abgelehnt" ? "Der KI-Dienst hat diese Anfrage nicht bearbeitet – hier ein regelbasierter Vorschlag." : HINWEIS_AUSFALL, `ki-${e.art}`);
162	    }
163	  }
164	
165	  // Textfälle: ohne Streaming-Wunsch eine normale Anfrage
166	  if (body.stream !== true) {
167	    try {
168	      const r = await erstellen(anfrage);
169	      await protokollieren(n, { ...prot, modus: "ki", tokensEin: r.nutzung.ein, tokensAus: r.nutzung.aus });
170	      return { ...basis, modus: "ki", ergebnis: { text: r.text.trim() }, hinweis: "" };
171	    } catch (e) {
172	      if (!(e instanceof KiFehler)) throw e;
173	      return regelAntwort(HINWEIS_AUSFALL, `ki-${e.art}`);
174	    }
175	  }
176	
177	  // Streaming: Verbindung (inkl. Wiederholungen) VOR dem Antworten aufbauen – scheitert sie, Regelmodus als JSON
178	  let strom;
179	  try {
180	    strom = await streamen(anfrage);
181	  } catch (e) {
182	    if (!(e instanceof KiFehler)) throw e;
183	    return regelAntwort(HINWEIS_AUSFALL, `ki-${e.art}`);
184	  }
185	
186	  const encoder = new TextEncoder();
187	  const lesbar = new ReadableStream({
188	    async start(controller) {
189	      const senden = (o) => controller.enqueue(encoder.encode(zeile(o)));
190	      let nutzung = { ein: 0, aus: 0 };
191	      let ergebnis = "ok";
192	      senden({ t: "start", ...basis, modus: "ki", hinweis: "" });
193	      try {
194	        for await (const e of strom.ereignisse()) {
195	          if (e.typ === "text") senden({ t: "text", text: e.text });
196	          else if (e.typ === "abgelehnt") {
197	            ergebnis = "ki-abgelehnt";
198	            senden({ t: "ersetzen", modus: "regel", ergebnis: def.regel(k, eingaben), hinweis: "Der KI-Dienst hat diese Anfrage nicht bearbeitet – hier ein regelbasierter Vorschlag." });
199	          } else if (e.typ === "ende") {
200	            nutzung = e.nutzung;
201	            if (e.stopReason === "max_tokens") senden({ t: "hinweis", hinweis: "Die Antwort wurde gekürzt." });
202	          }
203	        }
204	        senden({ t: "ende" });
205	      } catch (err) {
206	        ergebnis = "ki-abbruch";
207	        console.error("[plattform-ki] Stream abgebrochen:", err?.message);
208	        senden({ t: "ersetzen", modus: "regel", ergebnis: def.regel(k, eingaben), hinweis: HINWEIS_AUSFALL });
209	        senden({ t: "ende" });
210	      } finally {
211	        await protokollieren(n, { ...prot, modus: "ki", ergebnis, tokensEin: nutzung.ein, tokensAus: nutzung.aus });
212	        controller.close();
213	      }
214	    },
215	  });
216	  return new Response(lesbar, {
217	    status: 200,
218	    headers: { "Content-Type": "application/x-ndjson; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" },
219	  });
220	}
