228	//
229	// Konfiguration des KI-Assistenten (nur serverseitig). Der Assistent ist OPTIONAL:
230	// Ohne ANTHROPIC_API_KEY arbeitet jeder Anwendungsfall mit regelbasierten Vorschlägen
231	// (siehe regeln.js) – nie mit einem Fehler. Der Schlüssel verlässt nie den Server.
232	//
233	// Umgebungsvariablen (docs/PLATTFORM.md, Abschnitt „KI-Assistent“):
234	//   ANTHROPIC_API_KEY          Schlüssel der Claude API – ohne: regelbasierter Modus
235	//   KI_MODELL                  Modell-ID, Standard claude-opus-5-5
236	//   KI_TAGESKONTINGENT         Aufrufe je Konto und Tag (Standard 30), Backoffice: KI_TAGESKONTINGENT_ADMIN (Standard 150)
237	//   KI_AUS                     „1“ schaltet den KI-Modus ab (z. B. bei Störungen), Regeln bleiben aktiv
238	//   KI_FALLBACK                „aus“ deaktiviert den serverseitigen Ausweich-Modell-Mechanismus (fallbacks)
239	
240	export const STANDARD_MODELL = "claude-opus-5-5";
241	
242	/** Modelle, für die der serverseitige Ausweichmechanismus (`fallbacks: "default"`) gesetzt wird */
243	const MIT_FALLBACK = new Set(["claude-opus-5-5", "claude-opus-5", "claude-fable-5-1", "claude-sonnet-5-5"]);
244	
245	export const ANWENDUNGSFAELLE = {
246	  expose: { label: "Exposé-Assistent", rollen: ["anbieter"] },
247	  triage: { label: "Anfrage-Zusammenfassung & Triage", admin: true },
248	  frage: { label: "Frag das Projekt", rollen: ["investor", "anbieter"] },
249	  flaeche: { label: "Flächen-Assistent", rollen: ["flaeche", "landwirt"] },
250	  nachricht: { label: "Nachrichten-Entwurf" },
251	};
252	
253	export const FALL_IDS = Object.keys(ANWENDUNGSFAELLE);
254	
255	export function kiAktiv() {
256	  return !!String(process.env.ANTHROPIC_API_KEY || "").trim() && process.env.KI_AUS !== "1";
257	}
258	
259	export function kiModell() {
260	  return String(process.env.KI_MODELL || "").trim() || STANDARD_MODELL;
261	}
262	
263	export function mitFallback(modell = kiModell()) {
264	  return process.env.KI_FALLBACK !== "aus" && MIT_FALLBACK.has(modell);
265	}
