272	/** Tages-Kontingent je Konto (Aufrufe des Assistenten, KI- und Regelmodus) */
273	export function tagesKontingent(nutzer) {
274	  const admin = !!nutzer?.rollen?.includes("admin");
275	  return admin ? zahl(process.env.KI_TAGESKONTINGENT_ADMIN, 150) : zahl(process.env.KI_TAGESKONTINGENT, 30);
276	}
