 32	async function dateiLesen() {
 33	  if (zustand.cache) return zustand.cache;
 34	  try {
 35	    // synchron: kein awaited I/O, das React im Dev-Modus ins HTML übernehmen könnte (siehe demo/speicher.js)
 36	    zustand.cache = JSON.parse(readFileSync(DATEI, "utf8"));
 37	    if (!Array.isArray(zustand.cache)) zustand.cache = [];
 38	  } catch {
