 50	async function dateiAnhaengen(eintrag) {
 51	  return exklusiv(async () => {
 52	    const liste = await dateiLesen();
 53	    liste.push(eintrag);
 54	    if (liste.length > MAX_EINTRAEGE) liste.splice(0, liste.length - MAX_EINTRAEGE);
 55	    await fs.mkdir(path.dirname(DATEI), { recursive: true });
 56	    const tmp = `${DATEI}.${process.pid}.tmp`;
 57	    await fs.writeFile(tmp, JSON.stringify(liste));
 58	    await fs.rename(tmp, DATEI);
 59	  });
