 64	async function frappe(methode, args) {
 65	  if (!isApiConfigured() || !process.env.SERVER) throw new PlattformFehler(503, "Das Plattform-Backend (Frappe) ist nicht konfiguriert.");
 66	  const res = await fetch(`${API_BASE_URL}oekoinvest_app.plattform.api.ki.${methode}`, {
 67	    method: "POST",
 68	    headers: getApiHeaders(),
 69	    body: JSON.stringify(args),
 70	    cache: "no-store",
 71	    signal: AbortSignal.timeout(10000),
 72	  }).catch(() => null);
 73	  if (!res) throw new PlattformFehler(502, "Der Server ist vorübergehend nicht erreichbar.");
 74	  if (!res.ok) {
 75	    console.error(`[plattform-ki] Frappe ki.${methode}: HTTP ${res.status}`);
 76	    if (res.status === 403) throw new PlattformFehler(403, "Dafür fehlt Ihnen die Berechtigung.");
 77	    throw new PlattformFehler(502, "Der Server ist vorübergehend nicht erreichbar.");
 78	  }
 79	  return (await res.json().catch(() => ({})))?.message ?? null;
 80	}
