 84	/** Heutige Nutzung und Kontingent eines Kontos: { genutzt, limit, rest } */
 85	export async function kontingent(n) {
 86	  let limit = tagesKontingent(n);
 87	  let genutzt = 0;
 88	  if (backendName() === "frappe") {
 89	    const r = await frappe("nutzung_heute", { als_benutzer: n.id });
 90	    genutzt = Number(r?.anzahl) || 0;
 91	    if (Number(r?.limit) > 0) limit = Number(r.limit);
 92	  } else {
 93	    const heute = tagVon();
 94	    const liste = await dateiLesen();
 95	    for (let i = liste.length - 1; i >= 0; i--) {
 96	      const e = liste[i];
 97	      if (e.tag !== heute) {
 98	        if (e.tag < heute) break; // chronologisch angehängt
 99	        continue;
100	      }
101	      if (e.nutzerId === n.id) genutzt++;
102	    }
103	  }
104	  return { genutzt, limit, rest: Math.max(0, limit - genutzt) };
105	}
