107	/** Wirft 429, wenn das Tages-Kontingent aufgebraucht ist */
108	export async function kontingentPruefen(n) {
109	  const k = await kontingent(n);
110	  if (k.rest <= 0) {
111	    throw new PlattformFehler(429, `Ihr Tages-Kontingent für den Assistenten (${k.limit} Aufrufe) ist aufgebraucht. Morgen steht es wieder zur Verfügung.`, "kontingent");
112	  }
113	  return k;
114	}
