117	export async function protokollieren(n, { fall, modus, ergebnis = "ok", tokensEin = 0, tokensAus = 0, objektArt = "", objektId = "" }) {
118	  const am = new Date().toISOString();
119	  const eintrag = { am, tag: tagVon(am), nutzerId: n.id, fall, modus, ergebnis, tokensEin, tokensAus, objektArt, objektId };
120	  try {
121	    if (backendName() === "frappe") await frappe("nutzung_protokollieren", { ...eintrag, als_benutzer: n.id });
122	    else await dateiAnhaengen(eintrag);
