128	/** Auswertung für das Backoffice (nur Demo-Backend; in Frappe über die Listenansicht des DocTypes) */
129	export async function nutzungUebersicht({ tage = 30 } = {}) {
130	  if (backendName() === "frappe") return null;
131	  const grenze = tagVon(new Date(Date.now() - tage * 864e5).toISOString());
132	  const liste = (await dateiLesen()).filter((e) => e.tag >= grenze);
133	  const jeFall = {};
134	  for (const e of liste) {
135	    const f = (jeFall[e.fall] ||= { aufrufe: 0, ki: 0, regel: 0, tokensEin: 0, tokensAus: 0 });
136	    f.aufrufe++;
137	    f[e.modus === "ki" ? "ki" : "regel"]++;
138	    f.tokensEin += e.tokensEin || 0;
139	    f.tokensAus += e.tokensAus || 0;
140	  }
141	  return { tage, aufrufe: liste.length, konten: new Set(liste.map((e) => e.nutzerId)).size, jeFall };
142	}
143	// src/lib/plattform/ki/client.js
144	//
145	// Schlanker Client für die Claude Messages API (POST /v1/messages) per fetch – ohne SDK-Paket
146	// (Projektregel: keine neuen npm-Pakete). Nur serverseitig verwenden.
147	//
148	//  - Zeitlimit je Versuch, Wiederholung mit exponentiellem Backoff bei 408/409/429/5xx/529 und
149	//    Netzwerkfehlern (Retry-After wird beachtet, gedeckelt)
150	//  - Prompt-Caching: stabile System-Blöcke tragen cache_control (Präfix bleibt byte-identisch)
151	//  - Serverseitiger Ausweichmechanismus bei Ablehnung durch Sicherheitsklassifikatoren
152	//    (`fallbacks: "default"`, Beta-Header server-side-fallback-2026-07-01)
153	//  - stop_reason wird immer geprüft („refusal“, „max_tokens“), bevor Inhalte verwendet werden
154	//  - Fehlertexte enthalten nie den Schlüssel oder Antwortinhalte
155	
156	import { kiModell, mitFallback } from "./konfig";
157	
158	const API_URL = "https://api.anthropic.com/v1/messages";
159	const API_VERSION = "2023-06-01";
160	const FALLBACK_BETA = "server-side-fallback-2026-07-01";
161	const WIEDERHOLBAR = new Set([408, 409, 429, 500, 502, 503, 504, 529]);
162	
163	export class KiFehler extends Error {
164	  constructor(message, { status = 0, art = "fehler", wiederholbar = false } = {}) {
165	    super(message);
166	    this.name = "KiFehler";
167	    this.status = status;
168	    this.art = art; // fehler | abgelehnt | zeit | netz | konfig | abgeschnitten
169	    this.wiederholbar = wiederholbar;
170	  }
171	}
172	
173	const warte = (ms) => new Promise((r) => setTimeout(r, ms));
174	
175	function kopfzeilen() {
176	  const schluessel = String(process.env.ANTHROPIC_API_KEY || "").trim();
177	  if (!schluessel) throw new KiFehler("KI nicht konfiguriert.", { art: "konfig" });
178	  const h = { "content-type": "application/json", "x-api-key": schluessel, "anthropic-version": API_VERSION };
179	  if (mitFallback()) h["anthropic-beta"] = FALLBACK_BETA;
180	  return h;
181	}
182	
183	/**
184	 * Anfragekörper. `system` = Liste stabiler Textblöcke (werden gecacht), `kontext` + `aufgabe`
185	 * landen in der Nutzer-Nachricht (wechselnder Teil NACH dem Cache-Präfix).
186	 */
187	export function koerper({ system = [], nachricht, maxTokens = 4000, effort = "low", schema = null, stream = false }) {
188	  const modell = kiModell();
189	  const bloecke = system.filter(Boolean).map((text, i, alle) => ({
190	    type: "text",
191	    text,
192	    ...(i === alle.length - 1 ? { cache_control: { type: "ephemeral" } } : {}),
193	  }));
194	  const k = {
195	    model: modell,
196	    max_tokens: maxTokens,
197	    system: bloecke,
198	    messages: [{ role: "user", content: nachricht }],
199	    output_config: { effort, ...(schema ? { format: { type: "json_schema", schema } } : {}) },
200	  };
201	  if (mitFallback(modell)) k.fallbacks = "default";
202	  if (stream) k.stream = true;
203	  return k;
204	}
205	
206	function wartezeit(res, versuch) {
207	  const ra = Number(res?.headers?.get?.("retry-after"));
208	  if (Number.isFinite(ra) && ra > 0) return Math.min(ra * 1000, 8000);
209	  return Math.min(700 * 2 ** versuch + Math.random() * 300, 6000);
210	}
211	
212	/** fetch mit Zeitlimit und Wiederholung; liefert eine erfolgreiche Response (Body ungelesen) */
213	async function senden(body, { versuche = 3, zeitlimitMs = 45000, signal } = {}) {
214	  let letzter;
215	  for (let versuch = 0; versuch < versuche; versuch++) {
216	    let res;
217	    try {
218	      const zeit = AbortSignal.timeout(zeitlimitMs);
219	      res = await fetch(API_URL, {
220	        method: "POST",
221	        headers: kopfzeilen(),
222	        body: JSON.stringify(body),
223	        cache: "no-store",
224	        signal: signal ? AbortSignal.any([signal, zeit]) : zeit,
225	      });
226	    } catch (e) {
227	      if (e instanceof KiFehler) throw e;
228	      if (signal?.aborted) throw new KiFehler("Abgebrochen.", { art: "abbruch" });
229	      const zeitueberschreitung = e?.name === "TimeoutError" || e?.name === "AbortError";
230	      letzter = new KiFehler(zeitueberschreitung ? "Zeitüberschreitung beim KI-Dienst." : "KI-Dienst nicht erreichbar.", { art: zeitueberschreitung ? "zeit" : "netz", wiederholbar: true });
231	      if (versuch < versuche - 1) await warte(wartezeit(null, versuch));
232	      continue;
233	    }
234	    if (res.ok) return res;
235	    // Fehlertyp nur für das Server-Log – Inhalte der Antwort nie weitergeben
236	    let typ = "";
237	    try {
238	      typ = (await res.json())?.error?.type || "";
239	    } catch {
240	      /* kein JSON */
241	    }
242	    console.error(`[plattform-ki] Claude API HTTP ${res.status} ${typ}`);
243	    letzter = new KiFehler("KI-Dienst hat die Anfrage nicht verarbeitet.", { status: res.status, wiederholbar: WIEDERHOLBAR.has(res.status) });
244	    if (!letzter.wiederholbar) throw letzter;
245	    if (versuch < versuche - 1) await warte(wartezeit(res, versuch));
246	  }
247	  throw letzter || new KiFehler("KI-Dienst nicht erreichbar.");
248	}
249	
250	function nutzungAus(u = {}) {
251	  return {
252	    ein: (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0),
253	    aus: u.output_tokens || 0,
254	    cache: u.cache_read_input_tokens || 0,
255	  };
256	}
257	
258	function stopPruefen(stopReason) {
259	  if (stopReason === "refusal") throw new KiFehler("Der KI-Dienst hat die Anfrage abgelehnt.", { art: "abgelehnt" });
260	}
261	
262	/** Nicht-streamende Anfrage. Liefert { text, json?, stopReason, nutzung, modell } */
263	export async function erstellen(optionen) {
264	  const body = koerper({ ...optionen, stream: false });
265	  const res = await senden(body, { zeitlimitMs: optionen.zeitlimitMs || 60000, signal: optionen.signal });
266	  const m = await res.json();
267	  stopPruefen(m.stop_reason);
268	  const text = (m.content || []).filter((b) => b.type === "text").map((b) => b.text).join("");
269	  const out = { text, stopReason: m.stop_reason, nutzung: nutzungAus(m.usage), modell: m.model };
270	  if (optionen.schema) {
