281	/**
282	 * Streamende Anfrage. Wartet auf die Kopfzeilen (Fehler/Wiederholungen VOR dem ersten Token),
283	 * danach liefert `ereignisse()` Textstücke: { typ: "text", text } … { typ: "ende", stopReason, nutzung, modell }.
284	 * Eine Ablehnung mitten im Stream kommt als { typ: "abgelehnt" } (Teilausgabe verwerfen).
285	 */
286	export async function streamen(optionen) {
287	  const body = koerper({ ...optionen, stream: true });
288	  const res = await senden(body, { zeitlimitMs: optionen.zeitlimitMs || 120000, signal: optionen.signal });
289	  async function* ereignisse() {
290	    const reader = res.body.getReader();
291	    const decoder = new TextDecoder();
292	    let puffer = "";
293	    let nutzung = { ein: 0, aus: 0, cache: 0 };
294	    let stopReason = null;
295	    let modell = "";
296	    let textBloecke = new Set();
297	    try {
298	      for (;;) {
299	        const { value, done } = await reader.read();
300	        if (done) break;
301	        puffer += decoder.decode(value, { stream: true });
302	        let grenze;
303	        while ((grenze = puffer.indexOf("\n\n")) >= 0) {
304	          const roh = puffer.slice(0, grenze);
305	          puffer = puffer.slice(grenze + 2);
306	          const zeile = roh.split("\n").find((z) => z.startsWith("data:"));
307	          if (!zeile) continue;
308	          let e;
309	          try {
310	            e = JSON.parse(zeile.slice(5).trim());
311	          } catch {
312	            continue;
313	          }
314	          if (e.type === "message_start") {
315	            modell = e.message?.model || modell;
316	            const u = nutzungAus(e.message?.usage);
317	            nutzung = { ...u, aus: nutzung.aus };
318	          } else if (e.type === "content_block_start" && e.content_block?.type === "text") {
319	            textBloecke.add(e.index);
320	          } else if (e.type === "content_block_delta" && e.delta?.type === "text_delta" && textBloecke.has(e.index)) {
321	            yield { typ: "text", text: e.delta.text };
322	          } else if (e.type === "message_delta") {
323	            stopReason = e.delta?.stop_reason || stopReason;
324	            if (e.usage?.output_tokens) nutzung.aus = e.usage.output_tokens;
325	          } else if (e.type === "error") {
326	            console.error(`[plattform-ki] Stream-Fehler ${e.error?.type || ""}`);
327	            throw new KiFehler("KI-Dienst hat den Vorgang abgebrochen.", { art: "fehler" });
328	          }
329	        }
330	      }
331	    } finally {
332	      reader.releaseLock?.();
333	    }
334	    if (stopReason === "refusal") {
335	      yield { typ: "abgelehnt" };
336	      return;
337	    }
338	    yield { typ: "ende", stopReason, nutzung, modell };
339	  }
340	  return { ereignisse };
341	}

